(() => {
  const STATUSES = ['Parada','Iniciada','Avaliação interna','Aguardando retorno externo','Ajuste','Avaliação externa','Concluído'];
  const RECURRENCES = { weekly:'Semanal', biweekly:'Quinzenal', monthly:'Mensal', oneoff:'Avulsa' };
  const storeKey = window.__REACH_STORE_KEY__ || 'cliente-nunca-sem-post-v1';
  const themeKey = 'cliente-nunca-sem-post-theme';
  function applyTheme(theme) { document.documentElement.dataset.theme=theme; const button=document.querySelector('#theme-toggle'); if(button) { button.textContent=theme==='light'?'◐':'☀︎'; button.setAttribute('aria-label',theme==='light'?'Ativar modo escuro':'Ativar modo claro'); } }
  applyTheme(localStorage.getItem(themeKey) || (matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark'));
  let data = JSON.parse(localStorage.getItem(storeKey) || '{"clients":[]}');
  data.team ||= [];
  data.templates ||= [];
  data.notes ||= [];
  data.sectors ||= [];
  data.templates.forEach(model=>(model.tasks||[]).forEach(task=>{task.sector ||= task.title||'';}));
  const modelSectorNames=data.templates.flatMap(model=>(model.tasks||[]).map(task=>task.sector||task.title).filter(Boolean));
  data.sectors = [...new Set([...data.sectors,...modelSectorNames].map(s=>String(s).trim()).filter(Boolean))];
  const sectorAliases = {'edição de reels':'Edição de vídeo','edicao de reels':'Edição de vídeo'};
  function canonicalSector(value=''){const raw=String(value).trim(),key=raw.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const alias=sectorAliases[key];const existing=data.sectors.find(s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()===key);const result=alias||existing||raw;if(result&&!data.sectors.includes(result))data.sectors.push(result);return result;}
  data.team.forEach(m=>{m.isLeader ??= false;m.palette ??= 'purple';m.photo ??= '';});
  data.clients.forEach(c=>c.fronts.forEach(f=>{f.pendingStart ??= '';f.pendingEnd ??= '';f.urgent ??= false;f.deliveryOrder ??= 999;(f.tasks||[]).forEach(t=>{t.month ??= t.dueDate?.slice(0,7)||'';t.priority ??= 999;t.highlighted ??= false;t.pinned ??= false;t.urgent ??= false;t.sector ??= data.sectors.includes(t.title)?t.title:'';t.requiresReview ??= false;t.reviewText ??= '';t.reviewChecklist ??= '';t.startTime ??= '';t.endTime ??= '';t.location ??= '';t.attachments ??= '';t.reviewChips ??= [];});}));
  const activeMemberKey = 'cliente-nunca-sem-post-active-member';
  if (window.__REACH_USER_ID__ && data.team.some(member => member.id === window.__REACH_USER_ID__)) {
    localStorage.setItem(activeMemberKey, window.__REACH_USER_ID__);
  }
  let scheduleMonth = new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  const $ = s => document.querySelector(s);
  const id = () => crypto.randomUUID();
  const localDate = value => { const [y,m,d] = value.split('-').map(Number); return new Date(y,m-1,d); };
  const iso = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
  const today = () => { const d = new Date(); return new Date(d.getFullYear(),d.getMonth(),d.getDate()); };
  const fmt = value => new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'}).format(localDate(value));
  const save = () => {
    try { localStorage.setItem(storeKey, JSON.stringify(data)); } catch (error) { console.warn('Armazenamento local indisponível', error); }
    if (window.parent !== window) window.parent.postMessage({ type: 'reach-workspace:save', payload: data }, window.parent.location.origin);
  };
  const addDays = (date,n) => { const d = new Date(date); d.setDate(d.getDate()+n); return d; };
  const addMonths = (date,n) => { const d = new Date(date); const wanted=d.getDate(); d.setDate(1); d.setMonth(d.getMonth()+n); d.setDate(Math.min(wanted,new Date(d.getFullYear(),d.getMonth()+1,0).getDate())); return d; };
  const templateById = templateId => data.templates.find(t=>t.id===templateId);
  const templateTasks = templateId => (templateById(templateId)?.tasks || []).map(t=>({id:id(),title:t.title,sector:canonicalSector(t.sector||t.title),owner:t.owner||'',status:'Parada',month:'',priority:999,highlighted:false,pinned:false,dueDate:'',note:t.note||''}));
  const palette = {blue:'#3269db',pink:'#df438f',purple:'#7a52dc',orange:'#ec6939'};
  function applyProfilePalette(memberId=localStorage.getItem(activeMemberKey)) { const member=data.team.find(m=>m.id===memberId); document.documentElement.dataset.profilePalette=member?.palette||'purple'; }
  const orderedTasks = tasks => [...tasks].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||Number(b.highlighted)-Number(a.highlighted)||Number(a.priority)-Number(b.priority)||String(a.dueDate).localeCompare(String(b.dueDate)));
  function period(front) { const start=front.pendingStart?localDate(front.pendingStart):addDays(localDate(front.approvedUntil),1); let end; if(front.pendingEnd) end=localDate(front.pendingEnd); else if(front.recurrence==='weekly') end=addDays(localDate(front.approvedUntil),7); else if(front.recurrence==='biweekly') end=addDays(localDate(front.approvedUntil),14); else if(front.recurrence==='monthly') end=addMonths(localDate(front.approvedUntil),1); else end=front.oneOffDate ? localDate(front.oneOffDate) : start; return {start:iso(start),end:iso(end)}; }
  function risk(front) { const diff=Math.round((localDate(front.approvedUntil)-today())/86400000); const slack=diff-Number(front.leadDays); let level; if(diff<0) level='red'; else if(slack<=0) level='orange'; else if(slack<=2) level='yellow'; else level='green'; return {diff,slack,level}; }
  function allFronts() { return data.clients.flatMap(client=>client.fronts.map(front=>({client,front,...risk(front),period:period(front)}))).sort((a,b)=>({red:0,orange:1,yellow:2,green:3}[a.level]-{red:0,orange:1,yellow:2,green:3}[b.level]) || a.slack-b.slack); }
  function layout(html) { $('#app').innerHTML=html; document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',location.hash.startsWith('#'+a.dataset.route))); }
  function empty(action='Cadastrar primeiro cliente') { return `<section class="empty"><h2>Nenhum cliente cadastrado.</h2><p>Cadastre o primeiro cliente e sua primeira frente de conteúdo para começar a acompanhar o risco de ficar sem post.</p><button class="button primary" data-action="new-client">${action}</button></section>`; }
  function renderRisk() { const all=allFronts(), months=[...new Set(all.flatMap(x=>(x.front.tasks||[]).map(t=>t.month).filter(Boolean)))].sort(), selectedMonth=sessionStorage.getItem('risk-month')||'', selectedStatus=sessionStorage.getItem('risk-status')||''; const fronts=all.filter(x=>{const tasks=x.front.tasks||[];return (!selectedMonth||tasks.some(t=>t.month===selectedMonth))&&(!selectedStatus||tasks.some(t=>t.status===selectedStatus));}); if(!all.length) { const content=!data.clients.length ? empty() : `<section class="empty"><h2>Cadastre a primeira frente de conteúdo.</h2><p>Clientes sem frentes ainda não entram no painel de risco.</p>${data.clients.map(c=>`<button class="button" data-action="open-client" data-client="${c.id}">${esc(c.name)}</button>`).join(' ')}</section>`; return layout(`<div class="page-head"><div><h1>Painel de risco</h1><p>Clientes ordenados por urgência real.</p></div></div>${content}`); } layout(`<div class="page-head"><div><h1>Painel de risco</h1><p>Urgência real, status e mês de cada demanda.</p></div></div><section class="view-switch risk-filters"><label>Mês<select id="risk-month"><option value="">Todos os meses</option>${months.map(m=>`<option value="${m}" ${m===selectedMonth?'selected':''}>${new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(localDate(m+'-01'))}</option>`).join('')}</select></label><label>Status<select id="risk-status"><option value="">Todos os status</option>${STATUSES.map(s=>`<option ${s===selectedStatus?'selected':''}>${s}</option>`).join('')}</select></label></section>${fronts.length?`<section class="risk-list">${fronts.map(x=>{const task=orderedTasks((x.front.tasks||[]).filter(t=>(!selectedMonth||t.month===selectedMonth)&&(!selectedStatus||t.status===selectedStatus)))[0];return `<div class="risk-row ${x.level}" data-open-front="${x.client.id}|${x.front.id}"><div class="bar"></div><div><strong>${esc(x.client.name)} — ${esc(x.front.name)}</strong><small>${task?`${esc(task.title)} · ${esc(task.owner||'Sem responsável')}`:`${RECURRENCES[x.front.recurrence]} · antecedência de ${x.front.leadDays} dia(s)`}</small></div><div><span class="label">Aprovado até</span>${fmt(x.front.approvedUntil)}</div><div><span class="label">Próximo período pendente</span>${fmt(x.period.start)} → ${fmt(x.period.end)}</div><div class="risk-text">${x.level==='red'?'JÁ ESTÁ SEM POST':`${x.slack} dia(s) de folga`}</div><div class="chevron">›</div></div>`}).join('')}</section>`:`<section class="empty"><h2>Nenhuma demanda neste filtro.</h2><p>Altere o mês ou status para visualizar outras demandas.</p></section>`}`); }
  function renderTemplates() { layout(`<div class="page-head"><div><h1>Modelos de demanda</h1><p>Padronize tarefas e responsáveis. Cada modelo continua editável por cliente.</p></div><div><button class="button" data-action="add-suggested-templates">Criar modelos sugeridos</button><button class="button primary" data-action="new-template">Novo modelo</button></div></div>${data.templates.length?`<section class="template-grid">${data.templates.map(t=>`<article class="template-card"><span class="template-tag">${esc(t.kind||'Entrega')}</span><h2>${esc(t.name)}</h2><p>${t.tasks.length} tarefa(s) padronizada(s)</p><div class="template-tasks">${t.tasks.map(x=>`<span>${esc(x.title)}${x.owner?` · ${esc(x.owner)}`:''}</span>`).join('')}</div><div><button class="button" data-action="edit-template" data-template="${t.id}">Editar</button><button class="button danger" data-action="delete-template" data-template="${t.id}">Excluir</button></div></article>`).join('')}</section>`:`<section class="empty"><h2>Nenhum modelo cadastrado.</h2><p>Crie modelos para as entregas recorrentes. Ao aplicar em uma frente, suas tarefas e responsáveis aparecem automaticamente.</p><button class="button primary" data-action="add-suggested-templates">Criar modelos sugeridos</button></section>`}`); }
  function renderTeamDirectory() { layout(`<div class="page-head"><div><h1>Equipe</h1><p>Cadastre as pessoas que podem receber demandas e acesse a página individual de cada uma.</p></div><button class="button primary" data-action="new-member">Adicionar pessoa</button></div>${data.team.length?`<section class="team-grid">${data.team.map(m=>{const open=data.clients.flatMap(c=>c.fronts.flatMap(f=>(f.tasks||[]).filter(t=>t.owner===m.name&&t.status!=='Concluído'))).length;return `<article class="member-card" style="--member-color:${palette[m.palette]}"><div class="member-initial">${m.photo?`<img src="${m.photo}" alt="">`:esc(m.name.slice(0,1).toUpperCase())}</div><div><h2>${esc(m.name)}</h2><p>${m.isLeader?'Liderança · ':''}${esc(m.role||'Sem função definida')} · ${open} demanda(s) aberta(s)</p></div><div><button class="button" data-action="open-member" data-member="${m.id}">Ver página</button><button class="button" data-action="edit-member" data-member="${m.id}">Editar</button></div></article>`}).join('')}</section>`:`<section class="empty"><h2>Cadastre a primeira pessoa da equipe.</h2><p>Ela ficará disponível para atribuição em modelos, tarefas e páginas individuais.</p><button class="button primary" data-action="new-member">Adicionar pessoa</button></section>`}`); }
  function renderMyAccess() { const memberId=localStorage.getItem(activeMemberKey); if(memberId&&data.team.some(m=>m.id===memberId)) return renderMember(memberId); layout(`<section class="empty"><h2>Acesso individual.</h2><p>O acesso é definido na autenticação do sistema. Esta versão local não permite trocar de perfil pela página da equipe.</p><button class="button primary" data-action="open-team">Abrir equipe</button></section>`); }
  function renderMember(memberId) { const member=data.team.find(m=>m.id===memberId); if(!member) return go('time'); const own=[];const others=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído').forEach(t=>(t.owner===member.name?own:others).push({c,f,t})))); const section=(title,items,emptyText)=>`<section class="person"><h2>${title}</h2>${items.length?items.map(x=>taskHtml(x.c,x.f,x.t)).join(''):`<p class="help">${emptyText}</p>`}</section>`;layout(`<div class="page-head"><div><button class="button" data-action="open-team">‹ Equipe</button><h1 style="margin-top:16px">${esc(member.name)}</h1><p>${esc(member.role||'Membro da equipe')} · visão individual</p></div><button class="button" data-action="edit-member" data-member="${member.id}">Editar perfil</button></div>${section('Minhas demandas',own,'Nenhuma demanda aberta atribuída a esta pessoa.')}${section('Demandas abertas da equipe',others,'Nenhuma outra demanda aberta no momento.')}`); }
  function renderClient(clientId) { const client=data.clients.find(c=>c.id===clientId); if(!client) return go('risco'); layout(`<div class="client-head"><div><button class="button" data-action="back">‹ Painel de risco</button><h1 style="margin-top:16px">${esc(client.name)}</h1><p class="team">Equipe responsável: ${esc(client.team.join(', ') || 'não informada')}</p></div><div><button class="button primary" data-action="new-front" data-client="${client.id}">Adicionar frente</button><button class="button danger" data-action="delete-client" data-client="${client.id}">Excluir cliente</button></div></div><h2>Frentes de conteúdo</h2>${client.fronts.length ? client.fronts.map(f=>frontHtml(client,f)).join('') : `<section class="empty"><p>Este cliente ainda não tem frentes de conteúdo.</p><button class="button primary" data-action="new-front" data-client="${client.id}">Adicionar frente</button></section>`}`); }
  function frontHtml(client,f) { const p=period(f), r=risk(f), tasks=f.tasks||[], template=templateById(f.templateId); return `<article class="front"><div class="front-header"><div><h3>${esc(f.name)} <span class="pill ${r.level}">${r.level==='red'?'Sem post':`${r.slack} dia(s) de folga`}</span></h3><p class="help">${RECURRENCES[f.recurrence]} · ${f.leadDays} dia(s) de antecedência${template?` · modelo: ${esc(template.name)}`:''}</p></div><div><button class="button" data-action="edit-front" data-client="${client.id}" data-front="${f.id}">Editar frente</button><button class="button danger" data-action="delete-front" data-client="${client.id}" data-front="${f.id}">Excluir</button></div></div><div class="front-meta"><span>Aprovado até <b>${fmt(f.approvedUntil)}</b></span><span>Período pendente atual <b>${fmt(p.start)} → ${fmt(p.end)}</b></span><button class="button" data-action="update-approved" data-client="${client.id}" data-front="${f.id}">Atualizar aprovado até</button></div><div class="task-list"><strong>Tarefas deste período</strong>${tasks.length ? orderedTasks(tasks).map(t=>taskHtml(client,f,t)).join('') : '<p class="help">Ainda não há tarefas para este período.</p>'}<button class="button" data-action="apply-template" data-client="${client.id}" data-front="${f.id}">Aplicar modelo</button> <button class="button" data-action="new-task" data-client="${client.id}" data-front="${f.id}">Adicionar tarefa</button></div></article>`; }
  function taskHtml(c,f,t) { return `<div class="task ${t.highlighted?'highlighted':''} ${t.pinned?'pinned':''}"><div><strong>${t.pinned?'📌 ':''}${t.highlighted?'★ ':''}${esc(t.title)}</strong>${t.note?`<div class="note">${esc(t.note)}</div>`:''}</div><div>${esc(t.owner||'Sem responsável')}</div><select class="status" data-status="${c.id}|${f.id}|${t.id}">${STATUSES.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><div><span class="priority-badge">#${t.priority===999?'–':t.priority}</span>${t.month?` <span class="label">${new Intl.DateTimeFormat('pt-BR',{month:'short',year:'numeric'}).format(localDate(t.month+'-01'))}</span>`:t.dueDate?fmt(t.dueDate):'<span class="label">Sem prazo</span>'}</div><button class="button danger" title="Excluir tarefa" data-action="delete-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">×</button></div>`; }
  function renderSchedule() { const fronts=allFronts(), year=scheduleMonth.getFullYear(), month=scheduleMonth.getMonth(), days=new Date(year,month+1,0).getDate(); const monthName=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(scheduleMonth); if(!fronts.length) return layout(`<div class="page-head"><div><h1>Cronograma mensal</h1><p>Esta visão só desenha as coberturas já cadastradas.</p></div></div>${empty()}`); let rows=fronts.map(({client,front})=>{const approved=localDate(front.approvedUntil), deadline=addDays(approved,-Number(front.leadDays)); let cells=''; for(let d=1;d<=days;d++){const current=new Date(year,month,d); const cls=current<=approved?'covered':'uncovered'; cells+=`<div class="cell ${cls} ${iso(current)===iso(deadline)?'deadline':''}" title="${fmt(iso(current))}"></div>`;} return `<div class="name">${esc(client.name)} — ${esc(front.name)}</div>${cells}`}).join(''); layout(`<div class="page-head"><div><h1>Cronograma mensal</h1><p>Verde: coberto até a aprovação. Rosa: descoberto. Linha laranja: início da antecedência.</p></div><div class="month-nav"><button class="button" data-action="prev-month">‹</button><h1>${monthName}</h1><button class="button" data-action="next-month">›</button></div></div><div class="schedule"><div class="schedule-grid" style="--days:${days}"><div class="name">Cliente — frente</div>${Array.from({length:days},(_,i)=>`<div class="day">${i+1}</div>`).join('')}${rows}</div></div>`); }
  function renderTeam() { const view=sessionStorage.getItem('routine-view')||'equipe'; const tasks=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído').forEach(t=>tasks.push({c,f,t})))); const groupKey=x=>{if(view==='equipe')return x.t.owner||'Sem responsável';if(view==='dia')return x.t.dueDate?fmt(x.t.dueDate):'Sem prazo';if(view==='semana'){const d=x.t.dueDate?localDate(x.t.dueDate):null;if(!d)return 'Sem prazo';const start=addDays(d,-((d.getDay()+6)%7));return `Semana de ${fmt(iso(start))}`;}if(view==='mês')return x.t.month?new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(localDate(x.t.month+'-01')):'Sem mês definido';return 'Todas as demandas';}; const groups=tasks.reduce((out,x)=>{const key=groupKey(x);(out[key]??=[]).push(x);return out;},{});layout(`<div class="page-head"><div><h1>Rotinas</h1><p class="week-note">A mesma demanda, em diferentes visualizações para organizar a operação.</p></div></div><section class="view-switch">${[['equipe','Equipe'],['dia','Dia'],['semana','Semana'],['mês','Mês'],['tudo','Tudo']].map(([key,label])=>`<button class="button ${view===key?'primary':''}" data-action="set-routine-view" data-view="${key}">${label}</button>`).join('')}</section>${tasks.length?Object.entries(groups).map(([group,items])=>`<section class="person"><h2>${esc(group)}</h2>${orderedTasks(items.map(x=>x.t)).map(t=>{const x=items.find(y=>y.t.id===t.id);return taskHtml(x.c,x.f,t);}).join('')}</section>`).join(''):`<section class="empty"><h2>Nenhuma tarefa aberta.</h2><p>As demandas abertas das frentes de conteúdo aparecerão aqui e poderão ser vistas por equipe, dia, semana, mês ou tudo.</p></section>`}`); }
  function go(route) { location.hash='#'+route; }
  function esc(v='') { const d=document.createElement('div'); d.textContent=v; return d.innerHTML; }
  function modal(title,body,onSubmit) { $('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><h2>${title}</h2><form id="modal-form">${body}<div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button primary">Salvar</button></div></form></div></div>`; $('#modal-form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));}; }
  function clientForm(c={}) { return `<label>Nome do cliente<input required name="name" value="${esc(c.name||'')}" autofocus></label><label>Responsáveis da equipe <input name="team" value="${esc((c.team||[]).join(', '))}" placeholder="Separe os nomes por vírgula"></label><p class="help">Uma frente pode usar estes responsáveis nas tarefas.</p>`; }
  function frontForm(f={}) { const rec=f.recurrence||'weekly',p= f.approvedUntil?period(f):{start:'',end:''}; return `<label>Nome da frente<input required name="name" value="${esc(f.name||'')}"></label><div class="form-row"><label>Recorrência<select name="recurrence">${Object.entries(RECURRENCES).map(([k,v])=>`<option value="${k}" ${k===rec?'selected':''}>${v}</option>`).join('')}</select></label><label>Antecedência mínima (dias)<input required min="0" type="number" name="leadDays" value="${f.leadDays??3}"></label></div><label>Modelo de demanda<select name="templateId"><option value="">Sem modelo</option>${data.templates.map(t=>`<option value="${t.id}" ${t.id===f.templateId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Aprovado até<input required type="date" name="approvedUntil" value="${f.approvedUntil||''}"></label><div class="form-row"><label>Período pendente - início<input required type="date" name="pendingStart" value="${f.pendingStart||p.start}"></label><label>Período pendente - fim<input required type="date" name="pendingEnd" value="${f.pendingEnd||p.end}"></label></div><label id="oneoff-field" class="${rec==='oneoff'?'':'hidden'}">Data da entrega avulsa<input type="date" name="oneOffDate" value="${f.oneOffDate||''}"></label><p class="help">Este é o período que será trabalhado. Você pode ajustar o início e fim quando houver uma divergência pontual.</p>`; }
  function memberForm(m={}) { return `<label>Nome<input required name="name" value="${esc(m.name||'')}" autofocus></label><label>Função / especialidade<input name="role" value="${esc(m.role||'')}" placeholder="Ex.: Conteúdo, Direção, Design"></label><div class="form-row"><label>Paleta pessoal<select name="palette">${[['blue','Reach Blue'],['pink','Reach Pink'],['purple','Reach Purple'],['orange','Reach Orange']].map(([v,label])=>`<option value="${v}" ${v===(m.palette||'purple')?'selected':''}>${label}</option>`).join('')}</select></label><label>Foto de perfil<input type="file" accept="image/*" name="photo"></label></div><label class="check-row"><input type="checkbox" name="isLeader" ${m.isLeader?'checked':''}> Perfil de liderança</label><p class="help">A foto e a paleta aparecem no perfil da pessoa. A liderança define prioridades e acessos na versão conectada.</p>`; }
  function templateForm(t={}) { const tasks=(t.tasks||[]).map(x=>`${x.title}${x.owner?` | ${x.owner}`:''}`).join('\n');return `<label>Nome do modelo<input required name="name" value="${esc(t.name||'')}" placeholder="Ex.: Pauta de Feed"></label><label>Tipo<select name="kind"><option ${t.kind==='Planejamento'?'selected':''}>Planejamento</option><option ${(!t.kind||t.kind==='Entrega')?'selected':''}>Entrega</option><option ${t.kind==='Operação'?'selected':''}>Operação</option></select></label><label>Tarefas padronizadas<textarea required name="tasks" placeholder="Uma por linha. Use “Título | Responsável” para pré-definir alguém.">${esc(tasks)}</textarea></label><p class="help">Exemplo: Briefing | Júlia. Os responsáveis vêm da equipe, mas você pode ajustar qualquer tarefa depois.</p>`; }
  const photoData = file => !file?.size ? Promise.resolve('') : new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file);});
  function taskForm(t={}) { return `<label>Título<input required name="title" value="${esc(t.title||'')}"></label><div class="form-row"><label>Responsável<input name="owner" value="${esc(t.owner||'')}" list="team-members"></label><label>Status<select name="status">${STATUSES.map(s=>`<option ${s===(t.status||STATUSES[0])?'selected':''}>${s}</option>`).join('')}</select></label></div><datalist id="team-members">${[...new Set([...data.clients.flatMap(c=>c.team),...data.team.map(m=>m.name)])].map(x=>`<option value="${esc(x)}">`).join('')}</datalist><div class="form-row"><label>Mês da demanda<input type="month" name="month" value="${t.month||''}"></label><label>Ordem de prioridade<input min="1" type="number" name="priority" value="${t.priority&&t.priority!==999?t.priority:''}" placeholder="1 é a mais urgente"></label></div><div class="check-row"><label><input type="checkbox" name="highlighted" ${t.highlighted?'checked':''}> Destacar visualmente</label><label><input type="checkbox" name="pinned" ${t.pinned?'checked':''}> Fixar até concluir</label></div><label>Prazo (opcional)<input type="date" name="dueDate" value="${t.dueDate||''}"></label><label>Observação<textarea name="note">${esc(t.note||'')}</textarea></label>`; }
  function currentRoute() { return location.hash.slice(1).split('/')[0] || 'risco'; }
  function render() { const r=currentRoute(), memberId=r==='pessoa'?location.hash.split('/')[1]:undefined; applyProfilePalette(memberId); if(r==='cliente') renderClient(location.hash.split('/')[1]); else if(r==='cronograma') renderSchedule(); else if(r==='equipe') renderTeam(); else if(r==='time') renderTeamDirectory(); else if(r==='pessoa') renderMember(location.hash.split('/')[1]); else if(r==='meu-acesso') renderMyAccess(); else if(r==='modelos') renderTemplates(); else renderRisk(); bind(); }
  function bind() { document.querySelectorAll('[data-open-front]').forEach(el=>el.onclick=()=>{const [c]=el.dataset.openFront.split('|');location.hash='#cliente/'+c;}); document.querySelectorAll('[data-status]').forEach(s=>s.onchange=()=>changeStatus(s)); const month=$('#risk-month'),status=$('#risk-status');if(month)month.onchange=()=>{sessionStorage.setItem('risk-month',month.value);render();};if(status)status.onchange=()=>{sessionStorage.setItem('risk-status',status.value);render();}; }
  function find(cId,fId,tId) { const c=data.clients.find(x=>x.id===cId),f=c?.fronts.find(x=>x.id===fId),t=f?.tasks.find(x=>x.id===tId); return {c,f,t}; }
  function changeStatus(el) { const [cId,fId,tId]=el.dataset.status.split('|'), {f,t}=find(cId,fId,tId); const wasComplete=t.status==='Concluído'; t.status=el.value; save(); if(!wasComplete && t.status==='Concluído' && f.tasks.length && f.tasks.every(x=>x.status==='Concluído')) { const p=period(f); if(confirm(`Todas as tarefas deste período foram concluídas. Atualizar “aprovado até” desta frente para ${fmt(p.end)}?`)) { f.approvedUntil=p.end; f.tasks=templateTasks(f.templateId); save(); } } render(); }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]'); if(!b)return; const a=b.dataset.action,cid=b.dataset.client,fid=b.dataset.front,tid=b.dataset.task; if(a==='new-client') modal('Cadastrar cliente',clientForm(),fd=>{const c={id:id(),name:fd.get('name').trim(),team:fd.get('team').split(',').map(x=>x.trim()).filter(Boolean),fronts:[]};data.clients.push(c);save();$('#modal-root').innerHTML='';location.hash='#cliente/'+c.id;}); if(a==='open-client') location.hash='#cliente/'+cid; if(a==='new-front') modal('Adicionar frente de conteúdo',frontForm(),fd=>{const c=data.clients.find(x=>x.id===cid),templateId=fd.get('templateId');c.fronts.push({id:id(),name:fd.get('name').trim(),recurrence:fd.get('recurrence'),leadDays:Number(fd.get('leadDays')),approvedUntil:fd.get('approvedUntil'),oneOffDate:fd.get('oneOffDate'),templateId,tasks:templateTasks(templateId)});save();$('#modal-root').innerHTML='';render();}); if(a==='edit-front'){const {f}=find(cid,fid);modal('Editar frente de conteúdo',frontForm(f),fd=>{Object.assign(f,{name:fd.get('name').trim(),recurrence:fd.get('recurrence'),leadDays:Number(fd.get('leadDays')),approvedUntil:fd.get('approvedUntil'),oneOffDate:fd.get('oneOffDate'),templateId:fd.get('templateId')});save();$('#modal-root').innerHTML='';render();});} if(a==='new-task') modal('Adicionar tarefa',taskForm(),fd=>{const {f}=find(cid,fid);f.tasks.push({id:id(),title:fd.get('title').trim(),owner:fd.get('owner').trim(),status:fd.get('status'),month:fd.get('month'),priority:Number(fd.get('priority'))||999,highlighted:fd.get('highlighted')==='on',pinned:fd.get('pinned')==='on',dueDate:fd.get('dueDate'),note:fd.get('note').trim()});save();$('#modal-root').innerHTML='';render();}); if(a==='delete-task'&&confirm('Excluir esta tarefa?')){const {f}=find(cid,fid);f.tasks=f.tasks.filter(x=>x.id!==tid);save();render();} if(a==='delete-front'&&confirm('Excluir esta frente e suas tarefas?')){const c=data.clients.find(x=>x.id===cid);c.fronts=c.fronts.filter(x=>x.id!==fid);save();render();} if(a==='delete-client'&&confirm('Excluir este cliente e todas as suas frentes?')){data.clients=data.clients.filter(x=>x.id!==cid);save();go('risco');} if(a==='update-approved'){const {f}=find(cid,fid);modal('Atualizar aprovado até',`<label>Aprovado até<input required type="date" name="approvedUntil" value="${f.approvedUntil}"></label><p class="help">O período pendente será recalculado ao salvar.</p>`,fd=>{f.approvedUntil=fd.get('approvedUntil');save();$('#modal-root').innerHTML='';render();});} if(a==='prev-month'){scheduleMonth.setMonth(scheduleMonth.getMonth()-1);render();} if(a==='next-month'){scheduleMonth.setMonth(scheduleMonth.getMonth()+1);render();} if(a==='back')go('risco'); if(a==='close-modal')$('#modal-root').innerHTML=''; });
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,templateId=b.dataset.template,memberId=b.dataset.member,cid=b.dataset.client,fid=b.dataset.front;const parseTasks=raw=>raw.split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const [title,owner='']=line.split('|');return {title:title.trim(),owner:owner.trim()};}); if(a==='new-member')modal('Adicionar pessoa à equipe',memberForm(),fd=>{const m={id:id(),name:fd.get('name').trim(),role:fd.get('role').trim(),palette:fd.get('palette'),isLeader:fd.get('isLeader')==='on',photo:''};photoData(fd.get('photo')).then(photo=>{m.photo=photo;data.team.push(m);save();$('#modal-root').innerHTML='';render();});}); if(a==='edit-member'){const m=data.team.find(x=>x.id===memberId);modal('Editar pessoa',memberForm(m),fd=>{const oldName=m.name;m.name=fd.get('name').trim();m.role=fd.get('role').trim();m.palette=fd.get('palette');m.isLeader=fd.get('isLeader')==='on';data.clients.forEach(c=>{c.team=c.team.map(x=>x===oldName?m.name:x);c.fronts.forEach(f=>(f.tasks||[]).forEach(t=>{if(t.owner===oldName)t.owner=m.name;}));});data.templates.forEach(t=>t.tasks.forEach(x=>{if(x.owner===oldName)x.owner=m.name;}));photoData(fd.get('photo')).then(photo=>{if(photo)m.photo=photo;save();$('#modal-root').innerHTML='';render();});});} if(a==='open-member')location.hash='#pessoa/'+memberId; if(a==='open-team')go('time'); if(a==='set-routine-view'){sessionStorage.setItem('routine-view',b.dataset.view);render();} if(a==='new-template')modal('Novo modelo de demanda',templateForm(),fd=>{data.templates.push({id:id(),name:fd.get('name').trim(),kind:fd.get('kind'),tasks:parseTasks(fd.get('tasks'))});save();$('#modal-root').innerHTML='';render();}); if(a==='edit-template'){const t=templateById(templateId);modal('Editar modelo de demanda',templateForm(t),fd=>{t.name=fd.get('name').trim();t.kind=fd.get('kind');t.tasks=parseTasks(fd.get('tasks'));save();$('#modal-root').innerHTML='';render();});} if(a==='delete-template'&&confirm('Excluir este modelo? As frentes existentes não serão apagadas.')){data.templates=data.templates.filter(t=>t.id!==templateId);save();render();} if(a==='apply-template'){if(!data.templates.length){go('modelos');return;}modal('Aplicar modelo à frente',`<label>Modelo<select required name="templateId">${data.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><p class="help">As tarefas do modelo serão adicionadas à lista atual.</p>`,fd=>{const {f}=find(cid,fid),selected=fd.get('templateId');f.templateId=selected;f.tasks.push(...templateTasks(selected));save();$('#modal-root').innerHTML='';render();});} if(a==='add-suggested-templates'){const suggestions=[['Pauta de Feed do Instagram','Planejamento',['Estratégia Direção','Estratégia Equipe','Conteúdo','Avaliação Interna 1','Troca com Cliente','Documento de Conteúdo','Roteiros','Avaliação Interna 2','Agendamento de Produção','Produção de Conteúdo','Briefing','Legendas','Vídeos','Artes','Apresentação','Avaliação Interna Final','Avaliação Externa','Agendamento','Controle de Métricas']],['Stories Fixos do Instagram','Entrega',['Definição de Estratégia e Conteúdo','Avaliação Interna 1','Troca com Cliente','Recepção de Material','Briefing','Vídeos','Artes','Apresentação','Avaliação Interna Final','Avaliação Externa','Agendamento','Controle de Métricas']],['Stories Gravação Semanal','Entrega',['Definição de Estratégia e Conteúdo','Avaliação Interna 1','Troca com Cliente','Recepção de Material','Planejamento de Gravação','Agendamento do Cliente','Produção de Conteúdo','Briefing','Vídeos','Artes','Apresentação','Avaliação Interna Final','Avaliação Externa','Agendamento','Controle de Métricas']],['Dicas de Stories','Entrega',['Definição de Estratégia e Conteúdo','Avaliação Interna 1','Troca com Cliente','Recepção de Material','Briefing','Apresentação','Avaliação Interna Final','Avaliação Externa','Controle de Métricas']],['Gestão de TikTok','Operação',['Estratégia Direção','Estratégia Equipe','Conteúdo','Avaliação Interna 1','Troca com Cliente','Documento de Conteúdo','Roteiros','Avaliação Interna 2','Agendamento de Produção','Produção de Conteúdo','Briefing','Avaliação Interna 3','Edição de Fotos / Cadastro de Produtos','Solicitação de Cadastro de Produtos','Legendas','Vídeos','Apresentação','Avaliação Interna Final','Avaliação Externa','Confirmação de Cadastro de Produtos','Agendamento','Controle de Métricas']]];suggestions.forEach(([name,kind,tasks])=>{if(!data.templates.some(t=>t.name===name))data.templates.push({id:id(),name,kind,tasks:tasks.map(title=>({title,owner:''}))});});save();render();} });
  function renderClients() { layout(`<div class="page-head"><div><h1>Clientes</h1><p>Gerencie as tarefas fixas, a equipe e as frentes de cada cliente em um só lugar.</p></div><button class="button primary" data-action="new-client">Cadastrar cliente</button></div>${data.clients.length?`<section class="team-grid">${data.clients.map(c=>`<article class="member-card"><div class="member-initial">${esc(c.name.slice(0,1).toUpperCase())}</div><div><h2>${esc(c.name)}</h2><p>${c.fronts.length} frente(s) · ${esc(c.team.join(', ')||'Equipe não informada')}</p></div><div><button class="button" data-action="open-client" data-client="${c.id}">Gerir cliente</button></div></article>`).join('')}</section>`:`${empty()}`}`); }
  function renderReviews() { const items=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status.includes('Avaliação')||t.requiresReview).forEach(t=>items.push({c,f,t})))); layout(`<div class="page-head"><div><h1>Avaliações</h1><p>Tarefas que exigem revisão ou estão em etapa de avaliação.</p></div></div>${items.length?`<section class="person">${items.map(({c,f,t})=>`<article class="review-card"><div><span class="template-tag">${esc(t.status)}</span><h3>${esc(t.title)}</h3><p>${esc(c.name)} · ${esc(f.name)} · ${esc(t.owner||'Sem responsável')}</p>${t.reviewText?`<p class="review-text">${esc(t.reviewText)}</p>`:''}${t.reviewChecklist?`<p class="help">Checklist: ${esc(t.reviewChecklist)}</p>`:''}</div><button class="button" data-action="edit-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Avaliar / editar</button></article>`).join('')}</section>`:`<section class="empty"><h2>Nenhuma avaliação pendente.</h2><p>Ao marcar uma tarefa como “precisa de avaliação” ou movê-la para uma etapa de avaliação, ela aparecerá aqui.</p></section>`}`); }
  function taskForm(t={}) { return `<label>Título<input required name="title" value="${esc(t.title||'')}"></label><div class="form-row"><label>Responsável<input name="owner" value="${esc(t.owner||'')}" list="team-members"></label><label>Status<select name="status">${STATUSES.map(s=>`<option ${s===(t.status||STATUSES[0])?'selected':''}>${s}</option>`).join('')}</select></label></div><datalist id="team-members">${[...new Set([...data.clients.flatMap(c=>c.team),...data.team.map(m=>m.name)])].map(x=>`<option value="${esc(x)}">`).join('')}</datalist><div class="form-row"><label>Mês da demanda<input type="month" name="month" value="${t.month||''}"></label><label>Ordem de prioridade<input min="1" type="number" name="priority" value="${t.priority&&t.priority!==999?t.priority:''}" placeholder="1 é a mais urgente"></label></div><div class="check-row"><label><input type="checkbox" name="highlighted" ${t.highlighted?'checked':''}> Destacar visualmente</label><label><input type="checkbox" name="urgent" ${t.urgent?'checked':''}> Entrega urgente (alarme)</label><label><input type="checkbox" name="pinned" ${t.pinned?'checked':''}> Fixar até concluir</label><label><input type="checkbox" name="requiresReview" ${t.requiresReview?'checked':''}> Precisa de avaliação</label></div><label>Prazo<input type="date" name="dueDate" value="${t.dueDate||''}"></label><label>Orientação para avaliação<textarea name="reviewText">${esc(t.reviewText||'')}</textarea></label><label>Checklist de avaliação<textarea name="reviewChecklist" placeholder="Ex.: texto aprovado, arte revisada, links conferidos">${esc(t.reviewChecklist||'')}</textarea></label><label>Observação<textarea name="note">${esc(t.note||'')}</textarea></label>`; }
  function renderTeam() { const view=sessionStorage.getItem('routine-view')||'equipe',person=sessionStorage.getItem('routine-person')||'',tasks=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído'&&(!person||t.owner===person)).forEach(t=>tasks.push({c,f,t})))); const groupKey=x=>{if(view==='equipe')return x.t.owner||'Sem responsável';if(view==='dia')return x.t.dueDate?fmt(x.t.dueDate):'Sem prazo';if(view==='semana'){const d=x.t.dueDate?localDate(x.t.dueDate):null;return d?`Semana de ${fmt(iso(addDays(d,-((d.getDay()+6)%7))))}`:'Sem prazo';}if(view==='mês')return x.t.month?new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(localDate(x.t.month+'-01')):'Sem mês definido';if(view==='status')return x.t.status;return 'Todas as demandas';};const groups=tasks.reduce((out,x)=>{const key=groupKey(x);(out[key]??=[]).push(x);return out;},{}),people=[...new Set(data.team.map(m=>m.name).concat(data.clients.flatMap(c=>c.team)))].filter(Boolean);layout(`<div class="page-head"><div><h1>Rotinas</h1><p class="week-note">Organize a operação por equipe, data, mês, status ou uma visão geral.</p></div></div><section class="view-switch"><button class="button ${view==='equipe'?'primary':''}" data-action="set-routine-view" data-view="equipe">Equipe</button><button class="button ${view==='dia'?'primary':''}" data-action="set-routine-view" data-view="dia">Dia</button><button class="button ${view==='semana'?'primary':''}" data-action="set-routine-view" data-view="semana">Semana</button><button class="button ${view==='mês'?'primary':''}" data-action="set-routine-view" data-view="mês">Mês</button><button class="button ${view==='status'?'primary':''}" data-action="set-routine-view" data-view="status">Status</button><button class="button ${view==='tudo'?'primary':''}" data-action="set-routine-view" data-view="tudo">Tudo</button></section><label class="routine-filter">Pessoa<select id="routine-person"><option value="">Toda a equipe</option>${people.map(p=>`<option ${p===person?'selected':''}>${esc(p)}</option>`).join('')}</select></label>${tasks.length?Object.entries(groups).map(([group,items])=>`<section class="person"><h2>${esc(group)}</h2>${orderedTasks(items.map(x=>x.t)).map(t=>{const x=items.find(y=>y.t.id===t.id);return taskHtml(x.c,x.f,t);}).join('')}</section>`).join(''):`<section class="empty"><h2>Nenhuma tarefa aberta neste filtro.</h2></section>`}`); }
  function layout(html) { $('#app').innerHTML=html; if(currentRoute()==='risco'){const h=$('#app h1');if(h)h.textContent='Work';const p=$('#app .page-head p');if(p)p.textContent='Visão central das entregas, prazos e prioridades da operação.';} document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',location.hash.startsWith('#'+a.dataset.route))); }
  function injectTaskEditActions(){document.querySelectorAll('.task').forEach(row=>{if(row.querySelector('[data-action="edit-task"]'))return;const s=row.querySelector('[data-status]');if(!s)return;const [client,front,task]=s.dataset.status.split('|'),slot=row.firstElementChild;if(slot)slot.insertAdjacentHTML('beforeend',` <button class="task-edit" data-action="edit-task" data-client="${client}" data-front="${front}" data-task="${task}">Editar</button>`);});}
  function render() { const r=currentRoute(),memberId=r==='pessoa'?location.hash.split('/')[1]:undefined;applyProfilePalette(memberId);if(r==='cliente')renderClient(location.hash.split('/')[1]);else if(r==='clientes')renderClients();else if(r==='cronograma')renderSchedule();else if(r==='equipe')renderTeam();else if(r==='avaliacoes')renderReviews();else if(r==='time')renderTeamDirectory();else if(r==='pessoa')renderMember(location.hash.split('/')[1]);else if(r==='meu-acesso')renderMyAccess();else if(r==='modelos')renderTemplates();else renderRisk();bind();injectTaskEditActions();}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['new-front','edit-front','new-task','edit-task'].includes(b.dataset.action))return;e.stopImmediatePropagation();const a=b.dataset.action,cid=b.dataset.client,fid=b.dataset.front,tid=b.dataset.task;const taskFromForm=fd=>({title:fd.get('title').trim(),sector:canonicalSector(fd.get('sector')),owner:fd.get('owner').trim(),status:fd.get('status'),month:fd.get('month'),priority:Number(fd.get('priority'))||999,highlighted:fd.get('highlighted')==='on',pinned:fd.get('pinned')==='on',requiresReview:fd.get('requiresReview')==='on',reviewText:fd.get('reviewText').trim(),reviewChecklist:fd.get('reviewChecklist').trim(),dueDate:fd.get('dueDate'),note:fd.get('note').trim()});if(a==='new-front')modal('Adicionar frente de conteúdo',frontForm(),fd=>{const c=data.clients.find(x=>x.id===cid),templateId=fd.get('templateId');c.fronts.push({id:id(),name:fd.get('name').trim(),recurrence:fd.get('recurrence'),leadDays:Number(fd.get('leadDays')),approvedUntil:fd.get('approvedUntil'),pendingStart:fd.get('pendingStart'),pendingEnd:fd.get('pendingEnd'),oneOffDate:fd.get('oneOffDate'),templateId,tasks:templateTasks(templateId)});save();$('#modal-root').innerHTML='';render();});if(a==='edit-front'){const {f}=find(cid,fid);modal('Editar frente de conteúdo',frontForm(f),fd=>{Object.assign(f,{name:fd.get('name').trim(),recurrence:fd.get('recurrence'),leadDays:Number(fd.get('leadDays')),approvedUntil:fd.get('approvedUntil'),pendingStart:fd.get('pendingStart'),pendingEnd:fd.get('pendingEnd'),oneOffDate:fd.get('oneOffDate'),templateId:fd.get('templateId')});save();$('#modal-root').innerHTML='';render();});}if(a==='new-task')modal('Adicionar tarefa',taskForm(),fd=>{const {f}=find(cid,fid);f.tasks.push({id:id(),...taskFromForm(fd)});save();$('#modal-root').innerHTML='';render();});if(a==='edit-task'){const {t}=find(cid,fid,tid);modal('Editar tarefa',taskForm(t),fd=>{Object.assign(t,taskFromForm(fd));save();$('#modal-root').innerHTML='';render();});}},true);
  document.addEventListener('change',e=>{if(e.target.id==='routine-person'){sessionStorage.setItem('routine-person',e.target.value);render();}});
  const reviewPhrases=['Tudo certo','Aprovado para seguir','Ajustar texto','Ajustar informação','Ajustar estratégia','Ajustar CTA','Rever briefing','Rever formato','Falta informação','Precisa complementar'];
  const noteHtml=()=>`<section class="work-notes"><div class="section-title"><div><span class="eyebrow">Equipe</span><h2>Notas e lembretes</h2></div><button class="button" data-action="new-note">+ Nota</button></div>${data.notes.length?data.notes.slice().reverse().map(n=>`<article class="note-card"><p>${esc(n.text)}</p><div><span>${esc(n.author||'Equipe')}</span><button class="note-reaction" data-action="react-note" data-note="${n.id}">♡ ${n.likes||0}</button></div></article>`).join(''):`<p class="help">Deixe um lembrete rápido para toda a equipe.</p>`}</section>`;
  function renderRisk(){const fronts=allFronts(),active=data.team.find(m=>m.id===localStorage.getItem(activeMemberKey)),mine=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído'&&(!active||t.owner===active.name)).forEach(t=>mine.push({c,f,t}))));const rows=fronts.slice(0,6).map(x=>{const task=orderedTasks(x.front.tasks||[])[0];return `<div class="risk-row ${x.level}" data-open-front="${x.client.id}|${x.front.id}"><div class="bar"></div><div><strong>${esc(x.client.name)} — ${esc(x.front.name)}</strong><small>${task?`${esc(task.title)} · ${esc(task.owner||'Sem responsável')}`:`${RECURRENCES[x.front.recurrence]} · antecedência de ${x.front.leadDays} dia(s)`}</small></div><div><span class="label">Aprovado até</span>${fmt(x.front.approvedUntil)}</div><div><span class="label">Período de trabalho</span>${fmt(x.period.start)} → ${fmt(x.period.end)}</div><div class="risk-text">${x.level==='red'?'SEM POST':`${x.slack} dia(s) de folga`}</div><div class="chevron">›</div></div>`}).join('');layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Work</h1><p>Resumo de entregas, agenda e sinais que precisam de atenção.</p></div><div><button class="button" data-action="open-clients">Clientes</button><button class="button primary" data-action="new-client">Cadastrar cliente</button></div></div><div class="work-grid"><section class="work-main"><div class="section-title"><div><span class="eyebrow">Visão geral</span><h2>Entregas em acompanhamento</h2></div><a class="text-link" href="#clientes">Ver clientes</a></div>${fronts.length?`<section class="risk-list">${rows}</section>`:`${empty()}`}</section><aside class="my-agenda"><div class="section-title"><div><span class="eyebrow">Hoje</span><h2>Minha agenda</h2></div><span class="agenda-count">${mine.length}</span></div>${mine.length?orderedTasks(mine.map(x=>x.t)).slice(0,5).map(t=>{const x=mine.find(i=>i.t.id===t.id);return `<div class="agenda-item"><span class="agenda-dot"></span><div><strong>${esc(t.title)}</strong><small>${esc(x.c.name)} · ${t.dueDate?fmt(t.dueDate):'Sem data'}</small></div></div>`}).join(''):`<p class="help">As tarefas do seu perfil aparecerão aqui.</p>`}<a class="button" href="#equipe">Abrir rotinas</a></aside></div>${noteHtml()}`);}
  function renderTeam(){const view=sessionStorage.getItem('routine-view')||'lista',tasks=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído').forEach(t=>tasks.push({c,f,t}))));const card=x=>`<article class="routine-card"><span class="template-tag">${esc(x.t.status)}</span><h3>${esc(x.t.title)}</h3><p>${esc(x.c.name)} · ${esc(x.t.owner||'Sem responsável')}</p><small>${x.t.dueDate?fmt(x.t.dueDate):'Sem prazo'}</small></article>`;let content='';if(view==='quadros'){content=`<section class="status-board">${STATUSES.filter(s=>s!=='Concluído').map(s=>`<div class="status-column"><h2>${esc(s)}</h2>${tasks.filter(x=>x.t.status===s).map(card).join('')||'<p class="help">Sem tarefas</p>'}</div>`).join('')}</section>`;}else if(view==='calendario'){const dated=tasks.filter(x=>x.t.dueDate);content=`<section class="calendar-list">${dated.length?dated.sort((a,b)=>a.t.dueDate.localeCompare(b.t.dueDate)).map(x=>`<div class="calendar-event"><time>${fmt(x.t.dueDate)}</time>${card(x)}</div>`).join(''):'<p class="help">Inclua um prazo nas tarefas para vê-las no calendário.</p>'}</section>`;}else{content=tasks.length?`<section class="person">${tasks.map(x=>taskHtml(x.c,x.f,x.t)).join('')}</section>`:`<section class="empty"><h2>Nenhuma tarefa aberta.</h2></section>`;}layout(`<div class="page-head"><div><span class="eyebrow">Organização</span><h1>Rotinas</h1><p>Visualize tarefas em lista, por status ou como agenda de datas.</p></div></div><section class="view-switch"><button class="button ${view==='lista'?'primary':''}" data-action="set-routine-view" data-view="lista">Lista</button><button class="button ${view==='quadros'?'primary':''}" data-action="set-routine-view" data-view="quadros">Quadros</button><button class="button ${view==='calendario'?'primary':''}" data-action="set-routine-view" data-view="calendario">Calendário</button></section>${content}`);}
  function renderReviews(){const items=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status.includes('Avaliação')||t.requiresReview).forEach(t=>items.push({c,f,t}))));layout(`<div class="page-head"><div><span class="eyebrow">Qualidade</span><h1>Avaliações</h1><p>Revise, aprove ou devolva cada entrega com um retorno claro.</p></div></div>${items.length?`<section class="person">${items.map(({c,f,t})=>`<article class="review-card"><div><span class="template-tag">${esc(t.status)}</span><h3>${esc(t.title)}</h3><p>${esc(c.name)} · ${esc(t.owner||'Sem responsável')}</p><div class="review-checklist">${['Conteúdo alinhado ao briefing','Informações corretas','Texto claro e bem escrito','Direção alinhada à estratégia','Formato e quantidade corretos','Pronto para a próxima etapa'].map(i=>`<label><input type="checkbox" disabled> ${i}</label>`).join('')}</div><div class="review-chips">${reviewPhrases.map(p=>`<button class="chip ${t.reviewChips?.includes(p)?'selected':''}" data-action="toggle-review-chip" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}" data-phrase="${p}">${p}</button>`).join('')}</div></div><div class="review-actions"><button class="button" data-action="edit-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Editar</button><button class="button primary" data-action="approve-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Aprovar</button><button class="button danger" data-action="request-adjustments" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Pedir ajustes</button></div></article>`).join('')}</section>`:`<section class="empty"><h2>Nenhuma avaliação pendente.</h2><p>Quando uma tarefa entrar em avaliação, ela aparecerá nesta página.</p></section>`}`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='open-clients'){location.hash='#clientes';return;}if(a==='new-note'){modal('Nova nota',`<label>Lembrete ou informação<textarea required name="text"></textarea></label><label>Assinado por<input name="author" placeholder="Seu nome"></label>`,fd=>{data.notes.push({id:id(),text:fd.get('text').trim(),author:fd.get('author').trim(),likes:0});save();$('#modal-root').innerHTML='';render();});}if(a==='react-note'){const n=data.notes.find(n=>n.id===b.dataset.note);if(n){n.likes=(n.likes||0)+1;save();render();}}if(['approve-task','request-adjustments','toggle-review-chip'].includes(a)){const {t}=find(b.dataset.client,b.dataset.front,b.dataset.task);if(!t)return;if(a==='approve-task'){t.status='Concluído';t.requiresReview=false;}if(a==='request-adjustments'){t.status='Ajuste';t.requiresReview=true;t.note=`Ajustes solicitados: ${(t.reviewChips||[]).join(' · ')||'Revisar entrega.'}`;}if(a==='toggle-review-chip'){const p=b.dataset.phrase;t.reviewChips=t.reviewChips||[];t.reviewChips=t.reviewChips.includes(p)?t.reviewChips.filter(x=>x!==p):[...t.reviewChips,p];}save();render();}},true);
  function clientControlHtml(){const fronts=allFronts();return `<section class="client-control"><div class="section-title"><div><span class="eyebrow">Clientes</span><h2>Controle de entregas</h2><p>Visão de progresso e do período de trabalho de cada frente.</p></div><a class="text-link" href="#clientes">Gerir clientes</a></div>${fronts.length?`<div class="control-timeline">${fronts.map(({client,front,level,period:p})=>{const tasks=front.tasks||[],done=tasks.filter(t=>t.status==='Concluído').length,total=tasks.length||1,progress=Math.round(done/total*100);return `<button class="control-row ${level}" data-open-front="${client.id}|${front.id}"><div class="control-name"><strong>${esc(client.name)}</strong><small>${esc(front.name)} · ${progress}% concluído</small></div><div class="control-track"><span style="width:${progress}%"></span></div><div class="control-date">${fmt(p.start)}<br><small>${fmt(p.end)}</small></div><div class="control-avatars">${tasks.filter(t=>t.owner).slice(0,3).map(t=>`<i title="${esc(t.owner)}">${esc(t.owner.slice(0,1))}</i>`).join('')||'<i>–</i>'}</div></button>`;}).join('')}</div>`:`<p class="help">Cadastre clientes e frentes para acompanhar a operação aqui.</p>`}</section>`;}
  function addClientControl(){if(!['risco','equipe'].includes(currentRoute()))return;const target=currentRoute()==='risco'?$('.work-notes'):$('#app .view-switch');if(!target||$('#app .client-control'))return;target.insertAdjacentHTML(currentRoute()==='risco'?'beforebegin':'afterend',clientControlHtml());document.querySelectorAll('[data-open-front]').forEach(el=>el.onclick=()=>{const [c]=el.dataset.openFront.split('|');location.hash='#cliente/'+c;});}
  function render(){const r=currentRoute(),memberId=r==='pessoa'?location.hash.split('/')[1]:undefined;applyProfilePalette(memberId);if(r==='cliente')renderClient(location.hash.split('/')[1]);else if(r==='clientes')renderClients();else if(r==='cronograma')renderSchedule();else if(r==='equipe')renderTeam();else if(r==='avaliacoes')renderReviews();else if(r==='time')renderTeamDirectory();else if(r==='pessoa')renderMember(location.hash.split('/')[1]);else if(r==='meu-acesso')renderMyAccess();else if(r==='modelos')renderTemplates();else renderRisk();bind();injectTaskEditActions();addClientControl();}
  function openTaskModal(c,f,t){modal(`Revisar: ${esc(t.title)}`,`<section class="task-review-modal"><span class="template-tag">${esc(t.status)}</span><p class="help">${esc(c.name)} · ${esc(f.name)} · Responsável: ${esc(t.owner||'Sem responsável')}</p><h3>Material da tarefa</h3><p class="material-box">${esc(t.note||'Nenhuma descrição ou material foi adicionado a esta tarefa.')}</p>${t.attachments?`<p class="help">Anexos: ${esc(t.attachments)}</p>`:''}<h3>Checklist de conferência</h3><div class="review-checklist">${['Conteúdo está de acordo com o briefing','Informações estão corretas','Texto está claro e bem escrito','Direção está alinhada à estratégia','Formato e quantidade de posts está correto','Pronto para seguir para a próxima etapa'].map(i=>`<label><input type="checkbox"> ${i}</label>`).join('')}</div><h3>Parecer rápido</h3><div class="review-chips">${reviewPhrases.map(p=>`<button type="button" class="chip ${t.reviewChips?.includes(p)?'selected':''}" data-action="toggle-review-chip" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}" data-phrase="${p}">${p}</button>`).join('')}</div><label>Observação complementar (opcional)<textarea name="review-observation" placeholder="Somente se o parecer rápido não for suficiente."></textarea></label><div class="review-actions"><button type="button" class="button danger" data-action="request-adjustments" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Pedir ajustes</button><button type="button" class="button primary" data-action="approve-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Aprovar</button></div></section>`,()=>{});}
  function renderReviews(){const items=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status.includes('Avaliação')||t.requiresReview).forEach(t=>items.push({c,f,t}))));layout(`<div class="page-head"><div><span class="eyebrow">Qualidade</span><h1>Avaliações</h1><p>Abra a tarefa, confira o material e só então aprove ou devolva.</p></div></div>${items.length?`<section class="person">${items.map(({c,f,t})=>`<article class="review-card"><div><span class="template-tag">${esc(t.status)}</span><h3>${esc(t.title)}</h3><p>${esc(c.name)} · ${esc(t.owner||'Sem responsável')}</p><p class="help">${esc(t.note||'Sem descrição cadastrada')}</p></div><button class="button primary" data-action="open-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">Abrir tarefa para avaliar</button></article>`).join('')}</section>`:`<section class="empty"><h2>Nenhuma avaliação pendente.</h2><p>Quando uma tarefa entrar em avaliação, ela aparecerá aqui.</p></section>`}`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action="open-task"]');if(!b)return;e.stopImmediatePropagation();const {c,f,t}=find(b.dataset.client,b.dataset.front,b.dataset.task);if(t)openTaskModal(c,f,t);},true);
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(['approve-task','request-adjustments'].includes(b?.dataset.action))$('#modal-root').innerHTML='';});
  function renderClients(){const fronts=allFronts(),openTasks=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído').forEach(t=>openTasks.push({c,f,t}))));const sectors=[...new Set(openTasks.map(x=>{const m=data.team.find(p=>p.name===x.t.owner);return m?.role||x.t.owner||'Sem responsável';}))].filter(Boolean),next=orderedTasks(openTasks.map(x=>x.t)).slice(0,6);layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Clientes</h1><p>Controle central de frentes, setores e entregas que vêm a seguir.</p></div><button class="button primary" data-action="new-client">Cadastrar cliente</button></div><section class="clients-command"><div class="command-metrics"><article><span>Clientes</span><strong>${data.clients.length}</strong><small>na operação</small></article><article><span>Frentes</span><strong>${fronts.length}</strong><small>em acompanhamento</small></article><article><span>Demandas</span><strong>${openTasks.length}</strong><small>em aberto</small></article><article><span>Setores</span><strong>${sectors.length}</strong><small>em atividade</small></article></div><div class="command-columns"><section><div class="section-title"><div><span class="eyebrow">Em atividade</span><h2>Setores trabalhando</h2></div></div>${sectors.length?sectors.map(s=>{const related=openTasks.filter(x=>{const m=data.team.find(p=>p.name===x.t.owner);return (m?.role||x.t.owner||'Sem responsável')===s;});return `<div class="sector-row"><span class="sector-mark"></span><div><strong>${esc(s)}</strong><small>${related.length} demanda(s) · ${[...new Set(related.map(x=>x.c.name))].join(', ')}</small></div><span>${related.filter(x=>x.t.status==='Iniciada').length} em andamento</span></div>`}).join(''):'<p class="help">Atribua responsáveis às tarefas para visualizar os setores.</p>'}</section><section><div class="section-title"><div><span class="eyebrow">Próximas</span><h2>Demandas a seguir</h2></div><a class="text-link" href="#equipe">Abrir rotinas</a></div>${next.length?next.map(t=>{const x=openTasks.find(i=>i.t.id===t.id);return `<button class="next-demand" data-open-front="${x.c.id}|${x.f.id}"><span class="priority-badge">#${t.priority===999?'–':t.priority}</span><div><strong>${esc(t.title)}</strong><small>${esc(x.c.name)} · ${esc(t.owner||'Sem responsável')}</small></div><time>${t.dueDate?fmt(t.dueDate):'Sem prazo'}</time></button>`}).join(''):'<p class="help">Não há demandas abertas.</p>'}</section></div></section><h2>Carteira de clientes</h2>${data.clients.length?`<section class="team-grid">${data.clients.map(c=>{const tasks=c.fronts.flatMap(f=>f.tasks||[]),open=tasks.filter(t=>t.status!=='Concluído').length;return `<article class="member-card"><div class="member-initial">${esc(c.name.slice(0,1).toUpperCase())}</div><div><h2>${esc(c.name)}</h2><p>${c.fronts.length} frente(s) · ${open} demanda(s) aberta(s)</p></div><div><button class="button" data-action="open-client" data-client="${c.id}">Gerir cliente</button></div></article>`}).join('')}</section>`:`${empty()}`}`);}
  /* Clientes: cronograma mensal e pautas organizadas pelo estágio de produção. */
  function frontForm(f={}) { const rec=f.recurrence||'weekly',p=f.approvedUntil?period(f):{start:'',end:''}; return `<label>Nome da pauta<input required name="name" value="${esc(f.name||'')}"></label><div class="form-row"><label>Recorrência<select name="recurrence">${Object.entries(RECURRENCES).map(([k,v])=>`<option value="${k}" ${k===rec?'selected':''}>${v}</option>`).join('')}</select></label><label>Antecedência mínima (dias)<input required min="0" type="number" name="leadDays" value="${f.leadDays??3}"></label></div><label>Modelo de demanda<select name="templateId"><option value="">Sem modelo</option>${data.templates.map(t=>`<option value="${t.id}" ${t.id===f.templateId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Aprovado até<input required type="date" name="approvedUntil" value="${f.approvedUntil||''}"></label><div class="form-row"><label>Período pendente — início<input required type="date" name="pendingStart" value="${f.pendingStart||p.start}"></label><label>Período pendente — fim<input required type="date" name="pendingEnd" value="${f.pendingEnd||p.end}"></label></div><label id="oneoff-field" class="${rec==='oneoff'?'':'hidden'}">Data da entrega avulsa<input type="date" name="oneOffDate" value="${f.oneOffDate||''}"></label><p class="help">Defina o período desta pauta. Ajuste as datas sempre que houver uma exceção.</p>`; }
  function frontHtml(client,f) { const p=period(f),r=risk(f),tasks=f.tasks||[],template=templateById(f.templateId);return `<article class="front"><div class="front-header"><div><h3>${esc(f.name)} <span class="pill ${r.level}">${r.level==='red'?'Sem post':`${r.slack} dia(s) de folga`}</span></h3><p class="help">${RECURRENCES[f.recurrence]} · ${f.leadDays} dia(s) de antecedência${template?` · modelo: ${esc(template.name)}`:''}</p></div><div><button class="button" data-action="edit-front" data-client="${client.id}" data-front="${f.id}">Editar pauta</button><button class="button danger" data-action="delete-front" data-client="${client.id}" data-front="${f.id}">Excluir</button></div></div><div class="front-meta"><span>Aprovado até <b>${fmt(f.approvedUntil)}</b></span><span>Período pendente atual <b>${fmt(p.start)} → ${fmt(p.end)}</b></span><button class="button" data-action="update-approved" data-client="${client.id}" data-front="${f.id}">Atualizar aprovado até</button></div><div class="task-list"><strong>Demandas deste período</strong>${tasks.length?orderedTasks(tasks).map(t=>taskHtml(client,f,t)).join(''):'<p class="help">Ainda não há demandas para este período.</p>'}<button class="button" data-action="apply-template" data-client="${client.id}" data-front="${f.id}">Aplicar modelo</button> <button class="button" data-action="new-task" data-client="${client.id}" data-front="${f.id}">Adicionar demanda</button></div></article>`; }
  function renderClient(clientId){const client=data.clients.find(c=>c.id===clientId);if(!client)return go('risco');layout(`<div class="client-head"><div><button class="button" data-action="back">‹ Voltar ao Work</button><h1 style="margin-top:16px">${esc(client.name)}</h1><p class="team">Equipe responsável: ${esc(client.team.join(', ')||'não informada')}</p></div><div><button class="button primary" data-action="new-front" data-client="${client.id}">Adicionar pauta</button><button class="button danger" data-action="delete-client" data-client="${client.id}">Excluir cliente</button></div></div><h2>Pautas de entrega</h2>${client.fronts.length?client.fronts.map(f=>frontHtml(client,f)).join(''):`<section class="empty"><p>Este cliente ainda não tem pautas cadastradas.</p><button class="button primary" data-action="new-front" data-client="${client.id}">Adicionar pauta</button></section>`}`);}
  function monthInfo(){const year=scheduleMonth.getFullYear(),month=scheduleMonth.getMonth(),days=new Date(year,month+1,0).getDate();return {year,month,days,label:scheduleMonth.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})};}
  function roadmapRange(p,info){if(!p.start||!p.end)return null;const a=new Date(`${p.start}T12:00:00`),b=new Date(`${p.end}T12:00:00`),first=new Date(info.year,info.month,1),last=new Date(info.year,info.month,info.days,23,59,59);if(b<first||a>last)return null;const start=a<first?1:a.getDate(),end=b>last?info.days:b.getDate();return {start,end};}
  function monthlyRoadmapHtml(fronts,compact=false){const info=monthInfo(),rows=fronts.map(x=>({...x,range:roadmapRange(x.period,info)})).filter(x=>x.range);return `<section class="monthly-roadmap ${compact?'monthly-roadmap-compact':''}"><div class="section-title"><div><span class="eyebrow">${compact?'Controle de clientes':'Calendário de produção'}</span><h2>${compact?'Pautas do mês':'Acompanhamento mensal das pautas'}</h2><p>${compact?'Acompanhe o intervalo de cada pauta diretamente no fluxo de trabalho.':'Veja o período, o avanço e o que ainda precisa ser concluído.'}</p></div><div class="roadmap-nav"><button class="button icon-only" aria-label="Mês anterior" data-action="prev-month">‹</button><strong>${esc(info.label)}</strong><button class="button icon-only" aria-label="Próximo mês" data-action="next-month">›</button></div></div>${rows.length?`<div class="roadmap-scroll" style="--roadmap-days:${info.days}"><div class="roadmap-days"><span>Cliente / pauta</span>${Array.from({length:info.days},(_,i)=>`<b>${i+1}</b>`).join('')}</div><div class="roadmap-lines">${rows.map(({client,front,range,level})=>{const tasks=front.tasks||[],done=tasks.filter(t=>t.status==='Concluído').length,progress=tasks.length?Math.round(done/tasks.length*100):0,left=(range.start-1)/info.days*100,width=(range.end-range.start+1)/info.days*100;return `<button class="roadmap-line ${level}" data-open-front="${client.id}|${front.id}"><span class="roadmap-label"><strong>${esc(client.name)}</strong><small>${esc(front.name)} · ${progress}% concluído</small></span><span class="roadmap-track"><i class="roadmap-bar" style="left:${left}%;width:${width}%"><em>${esc(front.name)}</em></i></span></button>`;}).join('')}</div></div>`:`<p class="help">Não há pautas com período dentro deste mês.</p>`}</section>`;}
  function clientTaskCard(x){const {c,f,t}=x;return `<button class="client-task-card" data-open-front="${c.id}|${f.id}"><span class="task-priority ${t.highlighted?'is-highlighted':''}">${t.pinned?'⌖':'#'}${t.priority===999?'–':t.priority}</span><div><strong>${esc(t.title)}</strong><small>${esc(c.name)} · ${esc(f.name)}</small></div><time>${t.dueDate?fmt(t.dueDate):'Sem prazo'}</time></button>`;}
  function statusBoardHtml(items){return `<section class="status-client-board"><div class="section-title"><div><span class="eyebrow">Acompanhamento por status</span><h2>Demandas em produção</h2><p>Abra uma pauta para atualizar a entrega, o responsável ou a avaliação.</p></div></div><div class="client-status-columns">${STATUSES.map(status=>{const tasks=items.filter(x=>x.t.status===status);return `<section class="client-status-column"><header><span class="status-dot ${status==='Concluído'?'done':''}"></span><strong>${esc(status)}</strong><small>${tasks.length}</small></header><div>${tasks.length?tasks.map(clientTaskCard).join(''):'<p class="empty-column">Sem demandas</p>'}</div></section>`;}).join('')}</div></section>`;}
  function renderClients(){const fronts=allFronts(),items=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).forEach(t=>items.push({c,f,t}))));layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Clientes</h1><p>Períodos de produção e demandas organizadas por status.</p></div><button class="button primary" data-action="new-client">Cadastrar cliente</button></div>${monthlyRoadmapHtml(fronts)}${statusBoardHtml(items)}<section class="client-directory"><div class="section-title"><div><span class="eyebrow">Carteira</span><h2>Clientes cadastrados</h2></div></div>${data.clients.length?`<div class="client-directory-grid">${data.clients.map(c=>`<button class="client-directory-card" data-action="open-client" data-client="${c.id}"><span>${esc(c.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(c.name)}</strong><small>${c.fronts.length} pauta(s)</small></div><i>→</i></button>`).join('')}</div>`:empty()}</section>`);}
  function clientControlHtml(){const fronts=allFronts();return `<section class="client-control"><div class="section-title"><div><span class="eyebrow">Clientes</span><h2>Controle de entregas</h2><p>O mesmo acompanhamento mensal disponível na carteira de clientes.</p></div><a class="text-link" href="#clientes">Abrir clientes</a></div>${fronts.length?monthlyRoadmapHtml(fronts,true):'<p class="help">Cadastre clientes e pautas para acompanhar a operação aqui.</p>'}</section>`;}
  function googleAgendaUrl(t){if(!t.dueDate)return '#';const date=t.dueDate.replaceAll('-','');return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(t.title)}&dates=${date}/${date}&details=${encodeURIComponent(t.note||'')}`;}
  function taskHtml(c,f,t){return `<div class="task ${t.highlighted?'highlighted':''} ${t.pinned?'pinned':''}"><div><strong>${t.pinned?'📌 ':''}${t.highlighted?'★ ':''}${esc(t.title)}</strong>${t.note?`<div class="note">${esc(t.note)}</div>`:''}${t.dueDate?` <a class="task-calendar" href="${googleAgendaUrl(t)}" target="_blank" rel="noopener">Adicionar à agenda</a>`:''}</div><div>${esc(t.owner||'Sem responsável')}</div><select class="status" data-status="${c.id}|${f.id}|${t.id}">${STATUSES.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><div><span class="priority-badge">#${t.priority===999?'–':t.priority}</span>${t.month?` <span class="label">${new Intl.DateTimeFormat('pt-BR',{month:'short',year:'numeric'}).format(localDate(t.month+'-01'))}</span>`:t.dueDate?fmt(t.dueDate):'<span class="label">Sem prazo</span>'}</div><button class="button danger" title="Excluir tarefa" data-action="delete-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">×</button></div>`;}
  /* Agenda e acompanhamento visual de produção. */
  function taskHtml(c,f,t){return `<div class="task ${t.highlighted?'highlighted':''} ${t.pinned?'pinned':''} ${t.urgent?'urgent':''}"><div><strong>${t.pinned?'📌 ':''}${t.urgent?'⏰ ':''}${esc(t.title)}</strong>${t.note?`<div class="note">${esc(t.note)}</div>`:''}${t.dueDate?` <a class="task-calendar" href="${googleAgendaUrl(t)}" target="_blank" rel="noopener">Adicionar à agenda</a>`:''}</div><div>${esc(t.owner||'Sem responsável')}</div><select class="status" data-status="${c.id}|${f.id}|${t.id}">${STATUSES.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><div><span class="priority-badge">#${t.priority===999?'–':t.priority}</span>${t.month?` <span class="label">${new Intl.DateTimeFormat('pt-BR',{month:'short',year:'numeric'}).format(localDate(t.month+'-01'))}</span>`:t.dueDate?fmt(t.dueDate):'<span class="label">Sem prazo</span>'}</div><button class="task-flag ${t.highlighted?'active':''}" title="Destacar tarefa" data-action="toggle-highlight" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">★</button><button class="task-alarm ${t.urgent?'active':''}" title="Marcar como urgente" data-action="toggle-urgent" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">⏰</button><button class="button danger" title="Excluir tarefa" data-action="delete-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">×</button></div>`;}
  function coverageRange(front,info){const approved=localDate(front.approvedUntil),first=new Date(info.year,info.month,1),last=new Date(info.year,info.month,info.days,23,59,59);if(approved<first)return {start:1,end:0};return {start:1,end:Math.min(info.days,approved>last?info.days:approved.getDate())};}
  function monthlyRoadmapHtml(fronts,compact=false){const info=monthInfo(),now=today(),todayDay=now.getFullYear()===info.year&&now.getMonth()===info.month?now.getDate():0,days=Array.from({length:info.days},(_,i)=>`<b class="${i+1===todayDay?'is-today':''}">${i+1}</b>`).join(''),rows=fronts.map(({client,front,level})=>{const range=coverageRange(front,info),deadline=addDays(localDate(front.approvedUntil),-Number(front.leadDays)),mark=deadline.getFullYear()===info.year&&deadline.getMonth()===info.month?deadline.getDate():0,width=Math.max(0,range.end)/info.days*100,deadLeft=mark?(mark-.5)/info.days*100:-100,bar=range.end?`<i class="roadmap-bar" style="left:0;width:${width}%"><em>${esc(front.name)}</em></i>`:'',deadlineMark=mark?`<i class="roadmap-deadline" style="left:${deadLeft}%" title="Enviar até ${fmt(iso(deadline))}"></i>`:'';return `<button class="roadmap-line ${level}" data-open-front="${client.id}|${front.id}"><span class="roadmap-label"><strong>${esc(client.name)}</strong><small>${esc(front.name)} · aprovado até ${fmt(front.approvedUntil)}</small></span><span class="roadmap-track">${bar}${deadlineMark}</span></button>`;}).join('');return `<section class="monthly-roadmap ${compact?'monthly-roadmap-compact':''}"><div class="section-title"><div><span class="eyebrow">${compact?'Controle de clientes':'Calendário de produção'}</span><h2>${compact?'Cobertura aprovada no mês':'Acompanhamento mensal das pautas'}</h2><p>Cor: conteúdo aprovado. Traço: dia de envio. Linha: hoje.</p></div><div class="roadmap-nav"><button class="button icon-only" aria-label="Mês anterior" data-action="prev-month">‹</button><strong>${esc(info.label)}</strong><button class="button icon-only" aria-label="Próximo mês" data-action="next-month">›</button></div></div>${fronts.length?`<div class="roadmap-scroll" style="--roadmap-days:${info.days};--today:${todayDay||0}"><div class="roadmap-days"><span>Cliente / pauta</span>${days}</div><div class="roadmap-lines">${rows}</div></div>`:'<p class="help">Cadastre pautas para visualizar a cobertura mensal.</p>'}</section>`;}
  function agendaItems(person='',status=''){const out=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).filter(t=>t.status!=='Concluído'&&(!person||t.owner===person)&&(!status||t.status===status)).forEach(t=>out.push({c,f,t}))));return out;}
  function calendarHtml(items,mini=false){const info=monthInfo(),start=new Date(info.year,info.month,1),offset=(start.getDay()+6)%7,cells=Array.from({length:42},(_,i)=>{const day=i-offset+1,inMonth=day>=1&&day<=info.days,date=inMonth?iso(new Date(info.year,info.month,day)):'',list=inMonth?items.filter(x=>x.t.dueDate===date):[];return `<div class="agenda-day ${inMonth?'':'outside'} ${date===iso(today())?'today':''}"><b>${inMonth?day:''}</b>${list.slice(0,mini?1:3).map(x=>`<button data-open-front="${x.c.id}|${x.f.id}" class="agenda-event ${x.t.urgent?'urgent':''}" title="${esc(x.t.title)}">${x.t.urgent?'⏰ ':''}${esc(x.t.title)}</button>`).join('')}${list.length>(mini?1:3)?`<small>+${list.length-(mini?1:3)}</small>`:''}</div>`;}).join('');return `<div class="agenda-calendar ${mini?'agenda-mini':''}"><div class="agenda-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="agenda-month-grid">${cells}</div></div>`;}
  function renderTeam(){const person=sessionStorage.getItem('routine-person')||'',status=sessionStorage.getItem('routine-status')||'',items=agendaItems(person,status),people=[...new Set(data.team.map(m=>m.name).concat(data.clients.flatMap(c=>c.team)))].filter(Boolean);layout(`<div class="page-head"><div><span class="eyebrow">Organização</span><h1>Rotinas</h1><p>Calendário mensal da equipe para equilibrar disponibilidade e entregas.</p></div></div><section class="agenda-toolbar"><div class="roadmap-nav"><button class="button icon-only" data-action="prev-month">‹</button><strong>${monthInfo().label}</strong><button class="button icon-only" data-action="next-month">›</button></div><label>Pessoa<select id="routine-person"><option value="">Toda a equipe</option>${people.map(p=>`<option ${p===person?'selected':''}>${esc(p)}</option>`).join('')}</select></label><label>Status<select id="routine-status"><option value="">Todos os status</option>${STATUSES.filter(s=>s!=='Concluído').map(s=>`<option ${s===status?'selected':''}>${esc(s)}</option>`).join('')}</select></label></section><section class="team-calendar-panel">${calendarHtml(items)}<aside><span class="eyebrow">Carga no mês</span>${people.map(p=>`<div class="load-row"><span>${esc(p)}</span><b>${agendaItems(p,status).filter(x=>x.t.dueDate&&x.t.dueDate.slice(0,7)===`${monthInfo().year}-${String(monthInfo().month+1).padStart(2,'0')}`).length}</b></div>`).join('')||'<p class="help">Cadastre a equipe para acompanhar a disponibilidade.</p>'}</aside></section>`);}
  function renderAgenda(){const active=data.team.find(m=>m.id===localStorage.getItem(activeMemberKey)),person=sessionStorage.getItem('agenda-person')||(active?.name||''),status=sessionStorage.getItem('agenda-status')||'',people=[...new Set(data.team.map(m=>m.name).concat(data.clients.flatMap(c=>c.team)))].filter(Boolean),items=agendaItems(person,status),chronological=[...items].sort((a,b)=>(a.t.dueDate||'9999').localeCompare(b.t.dueDate||'9999'));layout(`<div class="page-head"><div><span class="eyebrow">Planejamento individual</span><h1>Minha agenda</h1><p>Semana, mês e lista cronológica das demandas da pessoa selecionada.</p></div></div><section class="agenda-toolbar"><div class="roadmap-nav"><button class="button icon-only" data-action="prev-month">‹</button><strong>${monthInfo().label}</strong><button class="button icon-only" data-action="next-month">›</button></div><label>Pessoa<select id="agenda-person"><option value="">Selecione uma pessoa</option>${people.map(p=>`<option ${p===person?'selected':''}>${esc(p)}</option>`).join('')}</select></label><label>Status<select id="agenda-status"><option value="">Todos os status</option>${STATUSES.filter(s=>s!=='Concluído').map(s=>`<option ${s===status?'selected':''}>${esc(s)}</option>`).join('')}</select></label></section><section class="personal-agenda"><div>${calendarHtml(items)}</div><aside><span class="eyebrow">Em ordem cronológica</span><h2>${person?esc(person):'Agenda'}</h2>${chronological.length?chronological.map(x=>`<button class="agenda-list-item ${x.t.urgent?'urgent':''}" data-open-front="${x.c.id}|${x.f.id}"><time>${x.t.dueDate?fmt(x.t.dueDate):'Sem prazo'}</time><div><strong>${x.t.urgent?'⏰ ':''}${esc(x.t.title)}</strong><small>${esc(x.c.name)} · ${esc(x.t.status)}</small></div></button>`).join(''):'<p class="help">Não há demandas abertas para este filtro.</p>'}</aside></section>`);}
  function renderRisk(){const fronts=allFronts(),active=data.team.find(m=>m.id===localStorage.getItem(activeMemberKey)),mine=agendaItems(active?.name||'');const mini=calendarHtml(mine,true),rows=fronts.slice(0,6).map(x=>{const task=orderedTasks(x.front.tasks||[])[0];return `<div class="risk-row ${x.level}" data-open-front="${x.client.id}|${x.front.id}"><div class="bar"></div><div><strong>${esc(x.client.name)} — ${esc(x.front.name)}</strong><small>${task?`${esc(task.title)} · ${esc(task.owner||'Sem responsável')}`:`Aprovado até ${fmt(x.front.approvedUntil)}`}</small></div><div><span class="label">Aprovado até</span>${fmt(x.front.approvedUntil)}</div><div class="risk-text">${x.level==='red'?'SEM POST':`${x.slack} dia(s) de folga`}</div><div class="chevron">›</div></div>`}).join('');layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Work</h1><p>Visão central de entregas, prazos e prioridades da operação.</p></div><div><button class="button" data-action="open-clients">Clientes</button><button class="button primary" data-action="new-client">Cadastrar cliente</button></div></div><div class="work-grid"><section class="work-main"><div class="section-title"><div><span class="eyebrow">Visão geral</span><h2>Entregas em acompanhamento</h2></div><a class="text-link" href="#clientes">Ver clientes</a></div>${fronts.length?`<section class="risk-list">${rows}</section>`:empty()}</section><aside class="my-agenda"><div class="section-title"><div><span class="eyebrow">Agenda</span><h2>Minha agenda</h2></div><span class="agenda-count">${mine.length}</span></div>${mini}<a class="button primary agenda-expand" href="#agenda">Abrir minha agenda</a></aside></div>${clientControlHtml()}${noteHtml()}`);}
  function render(){const r=currentRoute(),memberId=r==='pessoa'?location.hash.split('/')[1]:undefined;applyProfilePalette(memberId);if(r==='cliente')renderClient(location.hash.split('/')[1]);else if(r==='clientes')renderClients();else if(r==='cronograma')renderSchedule();else if(r==='equipe')renderTeam();else if(r==='agenda')renderAgenda();else if(r==='avaliacoes')renderReviews();else if(r==='time')renderTeamDirectory();else if(r==='pessoa')renderMember(location.hash.split('/')[1]);else if(r==='meu-acesso')renderMyAccess();else if(r==='modelos')renderTemplates();else renderRisk();bind();injectTaskEditActions();}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action="toggle-highlight"],[data-action="toggle-urgent"]');if(!b)return;e.preventDefault();const {c,f,t}=find(b.dataset.client,b.dataset.front,b.dataset.task);if(!t)return;if(b.dataset.action==='toggle-highlight')t.highlighted=!t.highlighted;else t.urgent=!t.urgent;save();render();});
  document.addEventListener('change',e=>{const k={"routine-person":"routine-person","routine-status":"routine-status","agenda-person":"agenda-person","agenda-status":"agenda-status"}[e.target.id];if(k){sessionStorage.setItem(k,e.target.value);render();}});
  /* Entregas gerais (pautas) e execuções têm sinais diferentes: alarme só na entrega. */
  function allFronts(){return data.clients.flatMap(client=>client.fronts.map(front=>({client,front,...risk(front),period:period(front)}))).sort((a,b)=>Number(b.front.urgent)-Number(a.front.urgent)||({red:0,orange:1,yellow:2,green:3}[a.level]-{red:0,orange:1,yellow:2,green:3}[b.level])||a.slack-b.slack);}
  function syncModelSectors(){data.templates.forEach(model=>(model.tasks||[]).forEach(task=>{task.sector=canonicalSector(task.sector||task.title);}));data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).forEach(task=>{if(!task.sector&&data.sectors.includes(task.title))task.sector=task.title;})));}
  function renderTemplates(){syncModelSectors();layout(`<div class="page-head"><div><span class="eyebrow">Padronização</span><h1>Modelos e setores</h1><p>Cada etapa cadastrada em um modelo já é um setor oficial de demanda.</p></div><div><button class="button" data-action="add-suggested-templates">Criar modelos sugeridos</button><button class="button primary" data-action="new-template">Novo modelo</button></div></div>${data.templates.length?`<section class="template-grid">${data.templates.map(t=>`<article class="template-card"><span class="template-tag">${esc(t.kind||'Entrega')}</span><h2>${esc(t.name)}</h2><p>${t.tasks.length} setor(es) / etapa(s) no modelo</p><div class="template-tasks">${t.tasks.map(x=>`<span>${esc(x.sector||x.title)}${x.owner?` · ${esc(x.owner)}`:''}</span>`).join('')}</div><div><button class="button" data-action="edit-template" data-template="${t.id}">Editar</button><button class="button danger" data-action="delete-template" data-template="${t.id}">Excluir</button></div></article>`).join('')}</section>`:`<section class="empty"><h2>Nenhum modelo cadastrado.</h2><p>Ao criar ou importar um modelo, seus nomes de tarefas passam a formar a base única de setores.</p><button class="button primary" data-action="add-suggested-templates">Criar modelos sugeridos</button></section>`}`);}
  function taskForm(t={}){syncModelSectors();return `<label>Título da tarefa<input required name="title" value="${esc(t.title||'')}"></label><div class="form-row"><label>Setor da demanda<input required name="sector" value="${esc(t.sector||'')}" list="task-sectors" placeholder="Escolha ou cadastre um setor"></label><label>Responsável<input name="owner" value="${esc(t.owner||'')}" list="team-members"></label></div><datalist id="task-sectors">${data.sectors.map(s=>`<option value="${esc(s)}">`).join('')}</datalist><datalist id="team-members">${[...new Set([...data.clients.flatMap(c=>c.team),...data.team.map(m=>m.name)])].map(x=>`<option value="${esc(x)}">`).join('')}</datalist><label>Status<select name="status">${STATUSES.map(s=>`<option ${s===(t.status||STATUSES[0])?'selected':''}>${s}</option>`).join('')}</select></label><div class="check-row"><label><input type="checkbox" name="highlighted" ${t.highlighted?'checked':''}> Destacar tarefa</label><label><input type="checkbox" name="pinned" ${t.pinned?'checked':''}> Fixar até concluir</label><label><input type="checkbox" name="requiresReview" ${t.requiresReview?'checked':''}> Precisa de avaliação</label></div><label>Prazo<input type="date" name="dueDate" value="${t.dueDate||''}"></label><label>Orientação para avaliação<textarea name="reviewText">${esc(t.reviewText||'')}</textarea></label><label>Checklist de avaliação<textarea name="reviewChecklist">${esc(t.reviewChecklist||'')}</textarea></label><label>Observação<textarea name="note">${esc(t.note||'')}</textarea></label><p class="help">A lista é formada automaticamente pelas etapas dos modelos; escreva um novo nome apenas quando for realmente um novo setor.</p>`;}
  function taskHtml(c,f,t){return `<div class="task ${t.highlighted?'highlighted':''} ${t.pinned?'pinned':''}"><div><strong>${t.pinned?'📌 ':''}${t.highlighted?'★ ':''}${esc(t.title)}</strong>${t.sector?`<span class="task-sector">${esc(t.sector)}</span>`:''}${t.origin?`<a class="task-origin" href="${esc(t.originUrl||'#')}" target="_top">Origem: ${esc(t.origin)}</a>`:''}${t.note?`<div class="note">${esc(t.note)}</div>`:''}${t.dueDate?` <a class="task-calendar" href="${googleAgendaUrl(t)}" target="_blank" rel="noopener">Adicionar à agenda</a>`:''}</div><div>${esc(t.owner||'Sem responsável')}</div><select class="status" data-status="${c.id}|${f.id}|${t.id}">${STATUSES.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><div>${t.dueDate?fmt(t.dueDate):'<span class="label">Sem prazo</span>'}</div><button class="task-flag ${t.highlighted?'active':''}" title="Destacar tarefa" data-action="toggle-highlight" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">★</button><button class="button danger" title="Excluir tarefa" data-action="delete-task" data-client="${c.id}" data-front="${f.id}" data-task="${t.id}">×</button></div>`;}
  function frontHtml(client,f){const p=period(f),r=risk(f),tasks=f.tasks||[],template=templateById(f.templateId);return `<article class="front ${f.urgent?'delivery-urgent':''}"><div class="front-header"><div><h3>${f.urgent?'⏰ ':''}${esc(f.name)} <span class="pill ${r.level}">${r.level==='red'?'Sem post':`${r.slack} dia(s) de folga`}</span></h3><p class="help">${RECURRENCES[f.recurrence]} · ${f.leadDays} dia(s) de antecedência${template?` · modelo: ${esc(template.name)}`:''}</p></div><div><button class="delivery-alarm ${f.urgent?'active':''}" title="Destacar entrega geral" data-action="toggle-front-urgent" data-client="${client.id}" data-front="${f.id}">⏰</button><button class="button" data-action="edit-front" data-client="${client.id}" data-front="${f.id}">Editar pauta</button><button class="button danger" data-action="delete-front" data-client="${client.id}" data-front="${f.id}">Excluir</button></div></div><div class="front-meta"><span>Aprovado até <b>${fmt(f.approvedUntil)}</b></span><span>Período pendente <b>${fmt(p.start)} → ${fmt(p.end)}</b></span><button class="button" data-action="update-approved" data-client="${client.id}" data-front="${f.id}">Atualizar aprovado até</button></div><div class="task-list"><strong>Tarefas de execução</strong>${tasks.length?orderedTasks(tasks).map(t=>taskHtml(client,f,t)).join(''):'<p class="help">Ainda não há tarefas para esta pauta.</p>'}<button class="button" data-action="apply-template" data-client="${client.id}" data-front="${f.id}">Aplicar modelo</button> <button class="button" data-action="new-task" data-client="${client.id}" data-front="${f.id}">Adicionar demanda</button></div></article>`;}
  function deliveryItems(){return allFronts().map(x=>({...x,due:x.period.end}));}
  function deliveryCalendarHtml(items,mini=false){const info=monthInfo(),start=new Date(info.year,info.month,1),offset=(start.getDay()+6)%7,cells=Array.from({length:42},(_,i)=>{const day=i-offset+1,inMonth=day>=1&&day<=info.days,date=inMonth?iso(new Date(info.year,info.month,day)):'',list=inMonth?items.filter(x=>x.due===date):[];return `<div class="agenda-day ${inMonth?'':'outside'} ${date===iso(today())?'today':''}"><b>${inMonth?day:''}</b>${list.slice(0,mini?1:3).map(x=>`<button data-open-front="${x.client.id}|${x.front.id}" class="agenda-event ${x.front.urgent?'urgent':''}" title="${esc(x.front.name)}">${x.front.urgent?'⏰ ':''}${esc(x.front.name)}</button>`).join('')}${list.length>(mini?1:3)?`<small>+${list.length-(mini?1:3)}</small>`:''}</div>`;}).join('');return `<div class="agenda-calendar ${mini?'agenda-mini':''}"><div class="agenda-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="agenda-month-grid">${cells}</div></div>`;}
  function monthlyRoadmapHtml(fronts,compact=false){const info=monthInfo(),now=today(),todayDay=now.getFullYear()===info.year&&now.getMonth()===info.month?now.getDate():0,days=Array.from({length:info.days},(_,i)=>`<b class="${i+1===todayDay?'is-today':''}">${i+1}</b>`).join(''),rows=fronts.map(({client,front,level})=>{const range=coverageRange(front,info),deadline=addDays(localDate(front.approvedUntil),-Number(front.leadDays)),mark=deadline.getFullYear()===info.year&&deadline.getMonth()===info.month?deadline.getDate():0,width=Math.max(0,range.end)/info.days*100,deadLeft=mark?(mark-.5)/info.days*100:-100,bar=range.end?`<i class="roadmap-bar" style="left:0;width:${width}%"><em>${front.urgent?'⏰ ':''}${esc(front.name)}</em></i>`:'',deadlineMark=mark?`<i class="roadmap-deadline" style="left:${deadLeft}%" title="Enviar até ${fmt(iso(deadline))}"></i>`:'';return `<button class="roadmap-line ${level} ${front.urgent?'delivery-urgent':''}" data-open-front="${client.id}|${front.id}"><span class="roadmap-label"><strong>${front.urgent?'⏰ ':''}${esc(client.name)}</strong><small>${esc(front.name)} · aprovado até ${fmt(front.approvedUntil)}</small></span><span class="roadmap-track">${bar}${deadlineMark}</span></button>`;}).join('');return `<section class="monthly-roadmap ${compact?'monthly-roadmap-compact':''}"><div class="section-title"><div><span class="eyebrow">${compact?'Controle de clientes':'Calendário de produção'}</span><h2>${compact?'Cobertura aprovada no mês':'Acompanhamento mensal das pautas'}</h2><p>Cor: conteúdo aprovado. Traço: dia de envio. Linha: hoje.</p></div><div class="roadmap-nav"><button class="button icon-only" data-action="prev-month">‹</button><strong>${esc(info.label)}</strong><button class="button icon-only" data-action="next-month">›</button></div></div>${fronts.length?`<div class="roadmap-scroll" style="--roadmap-days:${info.days};--today:${todayDay||0}"><div class="roadmap-days"><span>Cliente / pauta</span>${days}</div><div class="roadmap-lines">${rows}</div></div>`:'<p class="help">Cadastre pautas para visualizar a cobertura mensal.</p>'}</section>`;}
  function filterControls(scope,view,client,owner){const people=[...new Set(data.team.map(m=>m.name).concat(data.clients.flatMap(c=>c.team)))].filter(Boolean);return `<section class="agenda-toolbar filter-toolbar"><div class="view-switch">${[['status','Status'],['calendario','Calendário'],['quadro','Quadro'],['cronograma','Cronograma'],['setores','Setores']].map(([k,l])=>`<button class="button ${view===k?'primary':''}" data-action="set-${scope}-view" data-view="${k}">${l}</button>`).join('')}</div><label>Cliente<select id="${scope}-client"><option value="">Todos os clientes</option>${data.clients.map(c=>`<option value="${c.id}" ${client===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Responsável<select id="${scope}-owner"><option value="">Toda a equipe</option>${people.map(p=>`<option ${p===owner?'selected':''}>${esc(p)}</option>`).join('')}</select></label></section>`;}
  function sectorHtml(items){const groups=items.reduce((o,x)=>{const sector=x.t.sector||'Sem setor definido';(o[sector]??=[]).push(x);return o;},{});return `<section class="sector-board">${Object.entries(groups).map(([name,list])=>`<article><span class="eyebrow">Setor de demanda</span><h2>${esc(name)}</h2>${list.map(x=>`<button class="agenda-list-item" data-open-front="${x.c.id}|${x.f.id}"><time>${x.t.dueDate?fmt(x.t.dueDate):'Sem prazo'}</time><div><strong>${esc(x.t.title)}</strong><small>${esc(x.c.name)} · ${esc(x.t.owner||'Sem responsável')}</small></div></button>`).join('')}</article>`).join('')||'<p class="help">Cadastre o setor em cada tarefa para organizar esta visualização.</p>'}</section>`;}
  function statusBoardHtml(items){return `<section class="status-client-board"><div class="section-title"><div><span class="eyebrow">Acompanhamento por status</span><h2>Demandas em produção</h2><p>Abra uma pauta para atualizar a entrega, o responsável ou a avaliação.</p></div></div><div class="client-status-columns">${STATUSES.map(status=>{const tasks=items.filter(x=>x.t.status===status);return `<section class="client-status-column"><header><span class="status-dot ${status==='Concluído'?'done':''}"></span><strong>${esc(status)}</strong><small>${tasks.length}</small></header><div>${tasks.length?tasks.map(clientTaskCard).join(''):'<p class="empty-column">Sem demandas</p>'}</div></section>`;}).join('')}</div></section>`;}
  function renderClients(){const view=sessionStorage.getItem('clients-view')||'status',client=sessionStorage.getItem('clients-client')||'',owner=sessionStorage.getItem('clients-owner')||'',fronts=allFronts().filter(x=>!client||x.client.id===client).filter(x=>!owner||(x.front.tasks||[]).some(t=>t.owner===owner)),items=[];fronts.forEach(({client:c,front:f})=>(f.tasks||[]).forEach(t=>{if(!owner||t.owner===owner)items.push({c,f,t});}));const visual=view==='calendario'?monthlyRoadmapHtml(fronts):view==='cronograma'?monthlyRoadmapHtml(fronts):view==='setores'?sectorHtml(items):statusBoardHtml(items);layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Clientes</h1><p>Entregas filtradas por pauta, responsável e etapa de produção.</p></div><button class="button primary" data-action="new-client">Cadastrar cliente</button></div>${filterControls('clients',view,client,owner)}${visual}<section class="client-directory"><div class="section-title"><div><span class="eyebrow">Carteira</span><h2>Clientes cadastrados</h2></div></div>${data.clients.length?`<div class="client-directory-grid">${data.clients.map(c=>`<button class="client-directory-card" data-action="open-client" data-client="${c.id}"><span>${esc(c.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(c.name)}</strong><small>${c.fronts.length} pauta(s)</small></div><i>→</i></button>`).join('')}</div>`:empty()}</section>`);}
  function renderTeam(){const view=sessionStorage.getItem('routines-view')||'status',client=sessionStorage.getItem('routines-client')||'',owner=sessionStorage.getItem('routines-owner')||'',items=agendaItems(owner).filter(x=>!client||x.c.id===client),fronts=allFronts().filter(x=>!client||x.client.id===client).filter(x=>!owner||(x.front.tasks||[]).some(t=>t.owner===owner));const visual=view==='calendario'?`<section class="team-calendar-panel"><div>${calendarHtml(items)}</div></section>`:view==='quadro'?`<section class="status-board">${STATUSES.map(s=>`<article class="status-column"><h2>${esc(s)}</h2>${items.filter(x=>x.t.status===s).map(x=>clientTaskCard(x)).join('')||'<p class="empty-column">Sem demandas</p>'}</article>`).join('')}</section>`:view==='cronograma'?monthlyRoadmapHtml(fronts):view==='setores'?sectorHtml(items):statusBoardHtml(items);layout(`<div class="page-head"><div><span class="eyebrow">Organização</span><h1>Rotinas</h1><p>Uma mesma operação em status, calendário, quadro, cronograma ou setores.</p></div></div>${filterControls('routines',view,client,owner)}${visual}`);}
  function renderAgenda(){const active=data.team.find(m=>m.id===localStorage.getItem(activeMemberKey))||data.team[0],person=active?.name||'',view=sessionStorage.getItem('agenda-view')||'dia',status=sessionStorage.getItem('agenda-status')||'',items=agendaItems(person,status),todayItems=items.filter(x=>x.t.dueDate===iso(today())),visual=view==='calendario'?`<section class="personal-agenda"><div>${calendarHtml(items)}</div></section>`:view==='quadro'?`<section class="status-board">${STATUSES.map(s=>`<article class="status-column"><h2>${esc(s)}</h2>${items.filter(x=>x.t.status===s).map(x=>clientTaskCard(x)).join('')||'<p class="empty-column">Sem demandas</p>'}</article>`).join('')}</section>`:view==='status'?statusBoardHtml(items):view==='setores'?sectorHtml(items):`<section class="personal-agenda"><div><span class="eyebrow">Hoje</span><h2>${today().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</h2>${todayItems.length?todayItems.map(x=>clientTaskCard(x)).join(''):'<p class="help">Nenhuma tarefa de execução com prazo para hoje.</p>'}</div></section>`;layout(`<div class="page-head"><div><span class="eyebrow">Planejamento individual</span><h1>Minha agenda</h1><p>${person?`Agenda de ${esc(person)}`:'Nenhum perfil selecionado'} · somente as suas tarefas de execução.</p></div></div><section class="agenda-toolbar filter-toolbar"><div class="view-switch">${[['dia','Dia'],['calendario','Calendário'],['quadro','Quadro'],['status','Status'],['setores','Setores']].map(([k,l])=>`<button class="button ${view===k?'primary':''}" data-action="set-agenda-view" data-view="${k}">${l}</button>`).join('')}</div><div class="roadmap-nav"><button class="button icon-only" data-action="prev-month">‹</button><strong>${monthInfo().label}</strong><button class="button icon-only" data-action="next-month">›</button></div><label>Status<select id="agenda-status"><option value="">Todos os status</option>${STATUSES.filter(s=>s!=='Concluído').map(s=>`<option ${s===status?'selected':''}>${esc(s)}</option>`).join('')}</select></label></section>${visual}`);}
  function renderRisk(){const fronts=allFronts(),deliveries=deliveryItems(),rows=fronts.slice(0,6).map(x=>`<div class="risk-row ${x.level} ${x.front.urgent?'delivery-urgent':''}" data-open-front="${x.client.id}|${x.front.id}"><div class="bar"></div><div><strong>${x.front.urgent?'⏰ ':''}${esc(x.client.name)} — ${esc(x.front.name)}</strong><small>Entrega geral: ${fmt(x.period.start)} → ${fmt(x.period.end)}</small></div><div><span class="label">Aprovado até</span>${fmt(x.front.approvedUntil)}</div><div class="risk-text">${x.level==='red'?'SEM POST':`${x.slack} dia(s) de folga`}</div><div class="chevron">›</div></div>`).join('');layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Work</h1><p>Visão central das entregas gerais, prazos e prioridades.</p></div><div><button class="button" data-action="open-clients">Clientes</button><button class="button primary" data-action="new-client">Cadastrar cliente</button></div></div><div class="work-grid"><section class="work-main"><div class="section-title"><div><span class="eyebrow">Visão geral</span><h2>Entregas em acompanhamento</h2></div><a class="text-link" href="#clientes">Ver clientes</a></div>${fronts.length?`<section class="risk-list">${rows}</section>`:empty()}</section><div class="work-side-pair"><aside class="my-agenda"><div class="section-title"><div><span class="eyebrow">Agenda</span><h2>Minhas entregas</h2></div><span class="agenda-count">${deliveries.length}</span></div>${deliveryCalendarHtml(deliveries,true)}<a class="button primary agenda-expand" href="#agenda">Abrir minha agenda</a></aside>${noteHtml()}</div></div>${clientControlHtml()}`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action="toggle-front-urgent"]');if(!b)return;e.preventDefault();const found=find(b.dataset.client,b.dataset.front);if(!found?.f)return;found.f.urgent=!found.f.urgent;save();render();});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action^="set-clients-view"],[data-action^="set-routines-view"],[data-action^="set-agenda-view"]');if(!b)return;e.preventDefault();const scope=b.dataset.action.replace('set-','').replace('-view','');sessionStorage.setItem(`${scope}-view`,b.dataset.view);render();});
  document.addEventListener('change',e=>{const map={'clients-client':'clients-client','clients-owner':'clients-owner','routines-client':'routines-client','routines-owner':'routines-owner','agenda-status':'agenda-status'};if(map[e.target.id]){sessionStorage.setItem(map[e.target.id],e.target.value);render();}});
  function filterControls(scope,view,client,owner,sector){const people=[...new Set(data.team.map(m=>m.name).concat(data.clients.flatMap(c=>c.team)))].filter(Boolean);return `<section class="agenda-toolbar filter-toolbar"><div class="view-switch">${[['status','Status'],['calendario','Calendário'],['quadro','Quadro'],['cronograma','Cronograma'],['setores','Setores']].map(([k,l])=>`<button class="button ${view===k?'primary':''}" data-action="set-${scope}-view" data-view="${k}">${l}</button>`).join('')}</div><label>Cliente<select id="${scope}-client"><option value="">Todos</option>${data.clients.map(c=>`<option value="${c.id}" ${client===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Responsável<select id="${scope}-owner"><option value="">Toda a equipe</option>${people.map(p=>`<option ${p===owner?'selected':''}>${esc(p)}</option>`).join('')}</select></label><label>Setor<select id="${scope}-sector"><option value="">Todos os setores</option>${data.sectors.map(s=>`<option ${s===sector?'selected':''}>${esc(s)}</option>`).join('')}</select></label></section>`;}
  function sectorHtml(items){const groups=items.reduce((o,x)=>{const sector=x.t.sector||'Sem setor definido';(o[sector]??=[]).push(x);return o;},{});return `<section class="sector-board">${Object.entries(groups).map(([name,list])=>`<article class="sector-card"><header><span class="sector-icon">${esc(name.slice(0,1).toUpperCase())}</span><div><span class="eyebrow">Setor</span><h2>${esc(name)}</h2></div><b>${list.length}</b></header><p>${list.length===1?'1 demanda em produção':`${list.length} demandas em produção`}</p>${list.slice(0,4).map(x=>`<button class="agenda-list-item" data-open-front="${x.c.id}|${x.f.id}"><time>${x.t.dueDate?fmt(x.t.dueDate):'Sem prazo'}</time><div><strong>${esc(x.t.title)}</strong><small>${esc(x.c.name)} · ${esc(x.t.owner||'Sem responsável')}</small></div></button>`).join('')}${list.length>4?`<small class="sector-more">+${list.length-4} demanda(s)</small>`:''}</article>`).join('')||'<p class="help">Cadastre ou vincule um setor às tarefas para ver esta organização.</p>'}</section>`;}
  function renderClients(){const view=sessionStorage.getItem('clients-view')||'status',client=sessionStorage.getItem('clients-client')||'',owner=sessionStorage.getItem('clients-owner')||'',sector=sessionStorage.getItem('clients-sector')||'',items=[];data.clients.forEach(c=>c.fronts.forEach(f=>(f.tasks||[]).forEach(t=>{if((!client||c.id===client)&&(!owner||t.owner===owner)&&(!sector||t.sector===sector))items.push({c,f,t});})));const frontKeys=new Set(items.map(x=>`${x.c.id}|${x.f.id}`)),fronts=allFronts().filter(x=>frontKeys.has(`${x.client.id}|${x.front.id}`));const visual=view==='calendario'||view==='cronograma'?monthlyRoadmapHtml(fronts):view==='setores'?sectorHtml(items):view==='quadro'?`<section class="status-board">${STATUSES.map(s=>`<article class="status-column"><h2>${esc(s)}</h2>${items.filter(x=>x.t.status===s).map(clientTaskCard).join('')||'<p class="empty-column">Sem demandas</p>'}</article>`).join('')}</section>`:statusBoardHtml(items);layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Clientes</h1><p>Demandas em produção por status, calendário, setor e responsável.</p></div><button class="button primary" data-action="new-client">Cadastrar cliente</button></div>${filterControls('clients',view,client,owner,sector)}${visual}<section class="client-directory"><div class="section-title"><div><span class="eyebrow">Carteira</span><h2>Clientes cadastrados</h2></div></div>${data.clients.length?`<div class="client-directory-grid">${data.clients.map(c=>`<button class="client-directory-card" data-action="open-client" data-client="${c.id}"><span>${esc(c.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(c.name)}</strong><small>${c.fronts.length} pauta(s)</small></div><i>→</i></button>`).join('')}</div>`:empty()}</section>`);}
  function renderTeam(){const view=sessionStorage.getItem('routines-view')||'status',client=sessionStorage.getItem('routines-client')||'',owner=sessionStorage.getItem('routines-owner')||'',sector=sessionStorage.getItem('routines-sector')||'',items=agendaItems(owner).filter(x=>(!client||x.c.id===client)&&(!sector||x.t.sector===sector)),frontKeys=new Set(items.map(x=>`${x.c.id}|${x.f.id}`)),fronts=allFronts().filter(x=>frontKeys.has(`${x.client.id}|${x.front.id}`));const visual=view==='calendario'?`<section class="team-calendar-panel"><div>${calendarHtml(items)}</div></section>`:view==='quadro'?`<section class="status-board">${STATUSES.map(s=>`<article class="status-column"><h2>${esc(s)}</h2>${items.filter(x=>x.t.status===s).map(clientTaskCard).join('')||'<p class="empty-column">Sem demandas</p>'}</article>`).join('')}</section>`:view==='cronograma'?monthlyRoadmapHtml(fronts):view==='setores'?sectorHtml(items):statusBoardHtml(items);layout(`<div class="page-head"><div><span class="eyebrow">Organização</span><h1>Rotinas</h1><p>Visualize a operação por status, calendário, quadro, cronograma ou setor.</p></div></div>${filterControls('routines',view,client,owner,sector)}${visual}`);}
  function renderRisk(){const fronts=allFronts(),deliveries=deliveryItems(),rows=fronts.slice(0,6).map(x=>`<div class="risk-row ${x.level} ${x.front.urgent?'delivery-urgent':''}" data-open-front="${x.client.id}|${x.front.id}"><div class="bar"></div><div><strong>${x.front.urgent?'⏰ ':''}${esc(x.client.name)} — ${esc(x.front.name)}</strong><small>Entrega geral: ${fmt(x.period.start)} → ${fmt(x.period.end)}</small></div><button class="delivery-quick-alarm ${x.front.urgent?'active':''}" data-action="toggle-front-urgent" data-client="${x.client.id}" data-front="${x.front.id}">${x.front.urgent?'Alarme ativo':'Destacar entrega'}</button><div class="risk-text">${x.level==='red'?'SEM POST':`${x.slack} dia(s) de folga`}</div><div class="chevron">›</div></div>`).join('');layout(`<div class="page-head"><div><span class="eyebrow">Operação</span><h1>Work</h1><p>Visão central das entregas gerais, prazos e prioridades.</p></div><div><button class="button" data-action="open-clients">Clientes</button><button class="button primary" data-action="new-client">Cadastrar cliente</button></div></div><div class="work-grid"><section class="work-main"><div class="section-title"><div><span class="eyebrow">Visão geral</span><h2>Entregas em acompanhamento</h2></div><a class="text-link" href="#clientes">Ver clientes</a></div>${fronts.length?`<section class="risk-list">${rows}</section>`:empty()}</section><div class="work-side-pair"><aside class="my-agenda"><div class="section-title"><div><span class="eyebrow">Agenda</span><h2>Minhas entregas</h2></div><span class="agenda-count">${deliveries.length}</span></div>${deliveryCalendarHtml(deliveries,true)}<a class="button primary agenda-expand" href="#agenda">Abrir minha agenda</a></aside>${noteHtml()}</div></div>${clientControlHtml()}`);}
  document.addEventListener('change',e=>{const map={'clients-sector':'clients-sector','routines-sector':'routines-sector'};if(map[e.target.id]){sessionStorage.setItem(map[e.target.id],e.target.value);render();}});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action="toggle-front-urgent"]');if(!b)return;e.preventDefault();e.stopPropagation();const found=find(b.dataset.client,b.dataset.front);if(found?.f){found.f.urgent=!found.f.urgent;save();render();}},true);
  document.querySelector('#theme-toggle').onclick=()=>{const next=document.documentElement.dataset.theme==='light'?'dark':'light'; localStorage.setItem(themeKey,next); applyTheme(next); };
  document.addEventListener('change',e=>{if(e.target.name==='recurrence'){const x=$('#oneoff-field');if(x)x.classList.toggle('hidden',e.target.value!=='oneoff');}});
  syncModelSectors();
  localStorage.setItem(storeKey, JSON.stringify(data));
  window.addEventListener('hashchange',render); render();
})();
